(window.GIM_TS=window.GIM_TS||{})["Nedarim.2"]={"from":48,"a":[["\u0003ורבא אמר: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003אמר: אילו הייתי יודע שאבא ביניכם הייתי אומר \"פלוני ופלוני אסורין ואבא מותר\" —\u0004 במקרה זה \u0003כולם מותרין. לא נחלקו אלא באומר: אילו הייתי יודע שאבא ביניכם הייתי אומר \"כולכם אסורין חוץ מאבא\".\u0004","וזה הוא טעם המחלוקת: \u0003בית שמאי סברי לה\u0004 \u0005[סבורים]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר,\u0004 ש\u0003אמר: תפוס לשון ראשון,\u0004 שאם אדם אמר בתחילה דבר אחד ומיד אחר כך חזר ואמר דבר שונה — יש לתפוס את הגירסה הראשונה כמחייבת. ולכן כיון שאמר \"כולכם אסורים\" יש לתפוס לשון זו, ומשום כך כולם אסורים. ומה שאמר בסוף דבריו \"חוץ מאבא\" הוא רק פירוש לדברים שאמר בתחילה, שלא התכוון לאסור על אביו.","\u0003ובית הלל סברי לה\u0004 \u0005[סבורים]\u0006 \u0003כ\u0004דעת \u0003ר' יוסי\u0004 ש\u0003אמר: בגמר דבריו אדם נתפס\u0004 והולכים אחר לשון אחרונה שאמר. וכיון שבגמר דבריו חזר בו ממה שאמר בתחילה ואמר שאביו אינו אסור — אין כאן נדר כל עיקר.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב פפא לרבא\u0004 ממה ששנינו: \u0003כיצד אמר ר' עקיבא נדר שהותר מקצתו הותר כולו?\u0004 כגון שאמר \u0003\"קונם שאיני נהנה לכולכם\"\u0004 ו\u0003הותר אחד מהן\u0004 מאיזה טעם — \u0003הותרו כולם.\u0004 אם אמר \u0003\"שאיני נהנה לא לזה ולזה\",\u0004 אם \u0003הותר הראשון\u0004 בשרשרת זו — \u0003הותרו כולם,\u0004 אך אם \u0003הותר האחרון — האחרון\u0004 בלבד \u0003מותר וכולן אסורין.\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבה\u0004 הסבור שכשמעמיד דבריו ואומר: הייתי אומר \"כולכם חוץ מאבא\" כולם אסורים חוץ מאביו לדברי הכל, אבל כשמשנה דבריו ואומר: הייתי אומר \"פלוני ופלוני אסורים ואבא מותר\" — הותרו כולם לשיטת בית הלל, הרי הוא \u0003מוקים לה לרישא\u0004 \u0005[מעמיד,\u0006 מסביר \u0005את ההתחלה]\u0006 של דברי ר' עקיבא שהותרו כולם, שיש לפרשה לאחר שחזר בו \u0003דאמר\u0004 \u0005[שהוא אומר]\u0006 \u0003\"לזה ולזה\u0004 התכוונתי ולא לפלוני\u0003\",\u0004 והוא כדעת בית הלל.","\u0003וסיפא\u0004 \u0005[ובסוף]\u0006 דבריו של ר' עקיבא, שלא הותרו כולם — \u0003דאמר\u0004 \u0005[שהוא אומר]\u0006 \u0003\"לכולכם\",\u0004 שכשהוא חוזר בו אומר \"כולכם אסורים חוץ מפלוני\", ולדברי הכל.","\u0003אלא לדידך\u0004 \u0005[לשיטתך]\u0006 שאתה סבור שאם אמר: הייתי אומר \"פלוני ופלוני אסורים חוץ מאבא\" הכל מודים שכולם מותרים, ונחלקו באומר \"כולכם חוץ מאבא\", \u0003בשלמא רישא\u0004 \u0005[נניח\u0006 כי \u0005ההתחלה]\u0006 של דברי ר' עקיבא \u0003מוקים לה\u0004 \u0005[מעמיד,\u0006 מסביר \u0005אותה]\u0006 ש\u0003אמר \"לכולכם\"\u0004 כאשר חזר בו, והותרו כולם כשיטת בית הלל."],["\u0003אלא\u0004 לשיטתך, \u0003סיפא\u0004 \u0005[סופה]\u0006 המשכה של אותה משנה, במקרה ש\u0003אמר \"לזה ולזה\u0004 התכוונתי לאסור \u0003\"\u0004והותרו כולם, ששיטת \u0003ר' עקיבא היא,\u0004 לדבריך \u0003אמאי פליגי רבנן עליה\u0004 \u0005[מדוע חלוקים חכמים עליו]?\u0006 \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 אתה רבא ש\u0003דברי הכל מותר\u0004 כשמפרש \"לזה ולזה\"!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב פפא: \u0003ול\u0004שיטת \u0003רבה\u0004 שאתה תומך בה, \u0003ל\u0004שיטת \u0003ר' עקיבא מי ניחא סיפא\u0004 \u0005[האם נוח\u0006 לפרש את \u0005הסוף]?\u0006 שכן \u0003במאי מוקים לה\u0004 \u0005[במה\u0006 הוא \u0005מעמיד,\u0006 מפרש \u0005אותה]\u0006 — שחזר ו\u0003אמר \"לכולכם\",\u0004 אולם במקרה זה \u0003הי דין\u0004 \u0005[איזה\u0006 מהם\u0005]\u0006 \u0003הוא ראשון והי דין\u0004 \u0005[ואיזה]\u0006 \u0003הוא אחרון\u0004 אם אמר \"כולכם\"?","\u0003אלא\u0004 צריך לפרש כך: \u0003רישא\u0004 \u0005[בהתחלה]\u0006 מדובר ש\u0003אמר \"לכולכם\"\u0004 וכשיטת רבא שבנושא זה היתה המחלוקת, וזו שיטת בית הלל היא, האומרים שהותר הנדר כולו, \u0003וסיפא\u0004 \u0005[ובסוף],\u0006 בשני המקרים האחרונים, מדובר לא שפרט ואמר \"לזה ולזה אסור\" סתם, אלא \u0003כגון שתלאן\u0004 (תלה אותם) \u0003זה בזה, ואמר: \"פלוני\u0004 יהיה אסור \u0003כפלוני, ופלוני כפלוני\"\u0004 שאין עליהם איסור כולל אחד, אלא איסורם תלוי זה בזה, ולכן אם הותר הראשון, כל אלו שנתלו בו גם הם מותרים כמותו.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 כהסבר זה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על אותה משנה: אם \u0003הותר האמצעי\u0004 מתוך שרשרת כזו של נדורים — \u0003הימנו ולמטה,\u0004 כלומר, אלה שבאים אחריו \u0003מותרין,\u0004 ממנו \u0003ולמעלה,\u0004 אלה שלפניו — \u0003אסורין.\u0004 משמע שאכן מדובר כאן במקרה שתלה איסורם זה בזה, ולכן מאותו אדם שבו הותר האיסור — כל הבאים אחריו מותרים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אדא בר אהבה לרבא:\u0004 שנינו כי האומר \u0003\"קונם בצל שאני טועם שהבצל רע ללב\"\u0004 ו\u0003אמרו לו: והלא\u0004 הבצל \u0003הכופרי יפה ללב!\u0004 הרי זה \u0003הותר בכופרי. ולא בכופרי בלבד הותר אלא בכל הבצלים\u0004 הותר. ואכן, \u0003מעשה היה\u0004 באדם שנדר כך, \u0003והתירו ר' מאיר בכל הבצלים.\u0004","ומעתה, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן ש\u0003אמר\u0004 אותו אדם: \u0003אילו הייתי יודע שהכופרי יפה ללב הייתי אומר \"כל הבצלים אסורין וכופרי מותר\"?\u0004 ולפי זה קשה גם לרבה שאומר שבכגון זה הכל אוסרים, וגם לרבא שהסביר שבית שמאי האוסרים סבורים כר' מאיר, והרי ר' מאיר עצמו הוא המתיר כאן!","ודוחים: \u0003לא,\u0004 יש לפרש זאת \u0003באומר: אילו הייתי יודע שהכופרי יפה ללב הייתי אומר \"בצל פלוני ופלוני אסורין וכופרי מותר\". ור' מאיר\u0004 בפסקו זה הוא גם \u0003אליבא\u0004 \u0005[על פי\u0006 שיטת\u0005]\u0006 \u0003ר' עקיבא ו\u0004גם \u0003אליבא דרבנן\u0004 \u0005[על פי שיטת חכמים],\u0006 לפי האופן שרבא מפרש, שכשאמר \"פלוני ופלוני\" וכו' — לדעת הכל הותרו כולם.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרבא:\u0004 שנינו, \u0003ר' נתן אומר: יש נדר שמקצתו מותר ומקצתו אסור. כיצד? נדר מן הכלכלה\u0004 (סל), שאסר עצמו בנדר מכל מה שנמצא בתוך סל"],["\u0003והיו בה בנות שוח\u0004 (מין תאנים משובחות) \u0003ואמר: \"אילו הייתי יודע שבנות שוח בתוכה לא הייתי נודר\" — הכלכלה\u0004 ושאר התאנים שבה \u0003אסורה, בנות שוח מותרות. עד שבא ר' עקיבא ולימד: נדר שהותר מקצתו הותר כולו\u0004 וכולן מותרות. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן ש\u0003אמר\u0004 ופירש כך: \u0003אילו הייתי יודע שבנות שוח בתוכה הייתי אומר \"תאנים שחורות ולבנות אסורות, בנות שוח מותרות\" ו\u0004זו דעת \u0003ר' עקיבא היא, ופליגי רבנן\u0004 \u0005[וחלוקים חכמים]\u0006 עליו אף בזה? ולדעת רבא הרי כולם סבורים שהותר הכל במקרה כזה!","ודוחים: \u0003לא,\u0004 אפשר לומר כי מדובר כאן \u0003באומר: אילו הייתי יודע שבנות שוח בתוכה הייתי אומר \"כל הכלכלה אסורה ובנות שוח מותרות\".\u0004 וזו היא שיטת ר' עקיבא לדעת רבא.","ומעירים: לפי זה, \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי שנה את\u0006 הברייתא \u0005הזו ששנו חכמים]:\u0006 \u0003נדר מחמשה בני אדם כאחד, הותר לאחד מהם — הותרו כולן.\u0004 אם חזר בו ואמר \u0003\"\u0004כולם \u0003חוץ מאחד מהן\" — הוא\u0004 אותו אדם שהותר שאינו בכלל הנדר \u0003מותר, והן,\u0004 השאר, \u0003אסורין.\u0004","\u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שיטת \u0003רבה רישא\u0004 \u0005[בתחילה]\u0006 מדובר כשחזר ואמר \"זה וזה אסורים ואחד מותר\", ושיטת \u0003ר' עקיבא\u0004 היא, \u0003וסיפא\u0004 \u0005[וסופה]\u0006 \u0003דברי הכל. אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שיטת \u0003רבא סיפא רבנן\u0004 \u0005[סופה\u0006 כדעת \u0005חכמים]\u0006 \u0003ורישא\u0004 \u0005[וראשה]\u0006 כ\u0003דברי הכל.\u0004","\u0003נדרי אונסין\u0004 כיצד? \u0003הדירו חבירו שיאכל אצלו, וחלה הוא, או שחלה בנו\u0004 ובגלל זה לא בא, \u0003או שעכבו נהר\u0004 ואינו יכול לעבור — \u0003הרי אלו נדרי אונסין\u0004 ואין זה נדר.","מסופר: \u0003ההוא גברא דאתפיס זכוותא בבי דינא\u0004 \u0005[אדם אחד שהניח שטרי זכויות שלו בבית דין],\u0006 שהיה לו דין עם חבירו ורצה לדחות את הדיון לזמן אחר כדי לחפש ולהביא ראיות נוספות. וכיון שלא האמין בעל הדין שלו שישוב, התנה \u0003ואמר: אי\u0004 \u0005[אם]\u0006 \u0003לא אתינא\u0004 \u0005[אגיע]\u0006 \u0003עד תלתין יומין\u0004 \u0005[שלושים יום],\u0006 \u0003ליבטלון הני זכוותאי\u0004 \u0005[יתבטלו זכויותי אלה].\u0006 \u0003איתניס\u0004 \u0005[נאנס,\u0006 אירע לו אונס\u0005]\u0006 \u0003ולא אתא\u0004 \u0005[בא].\u0006 \u0003אמר רב הונא: בטיל זכוותיה\u0004 \u0005[בטלו זכויותיו],\u0006 שהרי לא בא למועד שקצב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 הלא \u0003אנוס הוא, ו\u0004כלל הוא: \u0003אנוס רחמנא פטריה\u0004 \u0005[התורה פטרה אותו]\u0006 מאחריות למה שעושה מחמת אונס, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בנערה האנוסה: \u0003\"ולנערה לא תעשה דבר\"\u0004 (דברים כב, כו).","\u0003וכי תימא קטלא שאני\u0004 \u0005[ואם תאמר\u0006 שלגבי עונש \u0005מיתה שונה]\u0006 הדין, כי עונש מוות הוא חמור ביותר, ולענין זה מקילים עליה ואין ממיתים אותה, אבל לשאר דברים אונס נחשב כרצון, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003נדרי אונסין\u0004 כיצד? \u0003הדירו חבירו שיאכל אצלו, וחלה הוא או שחלה בנו או שעיכבו נהר — הרי אלו נדרי אונסין\u0004 שאינו מחוייב בהם כלל!","ושואלים: \u0003ול\u0004דעת \u0003רבא, מאי שנא מהא דתנן\u0004 \u0005[במה שונה\u0006 דבר זה \u0005מזו ששנינו\u0006 במשנה\u0005]:\u0006 האומר לאשתו \u0003\"הרי זה גיטיך מעכשיו אם לא באתי מכאן עד שנים עשר חדש\" ומת בתוך שנים עשר חדש — הרי זה גט\u0004 מעכשיו. ו\u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003והא מינס איתניס\u0004 \u0005[והרי נאנס]\u0006 בכך, שאין אונס גדול ממיתה! ודוחים: \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003דלמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006"],["\u0003דאי הוה ידע דמית\u0004 \u0005[שאם היה יודע ש\u0006הוא \u0005מת]\u0006 בתוך השנה \u0003מן לאלתר הוה גמר ויהיב גיטא\u0004 \u0005[מיד היה גומר\u0006 בדעתו \u0005ונותן\u0006 לה \u0005גט].\u0006 שהרי מתחילה לא נתן לה גט זה אלא כדי שלא תזדקק לייבום, ואנו הולכים אחר כוונתו. מה שאין כן במקרה שלפנינו שהתפיס זכויותיו, שלא היתה כוונתו מתחילה לוותר עליהן.","ושואלים עוד על דברי רבא: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 דבר זה \u0003מההוא\u0004 \u0005[מאותו\u0006 אדם\u0005]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לשליחים שמסר בידם גט: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא אתינא\u0004 \u0005[אבוא]\u0006 \u0003מכאן\u0004 (מהיום) ו\u0003עד תלתין יומין\u0004 \u0005[שלושים יום]\u0006 \u0003ליהוי גיטא\u0004 \u0005[\u0006ש\u0005יהיה גט]\u0006 גמור אותו גט שהפקדתי בידכם. \u0003אתא\u0004 \u0005[הגיע]\u0006 למקום ביום השלושים \u0003ופסקיה מעברא\u0004 \u0005[ו\u0006אולם \u0005הפסיקה אותו המעבורת],\u0006 שלא מצא מעבורת לעבור בה את הנהר. \u0003אמר להו\u0004 \u0005[להם]\u0006 לאנשים בצד השני: \u0003חזו דאתאי, חזו דאתאי\u0004 \u0005[ראו שבאתי, ראו שבאתי]!\u0006 \u0003ואמר שמואל: לא שמיה מתייא\u0004 \u0005[אין שמה ביאה]\u0006 ולא נחשב לו שהגיע. ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003והא מינס אניס\u0004 \u0005[והרי אנוס\u0006 הוא\u0005]!\u0006","ודוחים: \u0003דלמא אונסא דמיגליא שאני\u0004 \u0005[שמא אונס ש\u0006הוא \u0005גלוי\u0006 וידוע מראש \u0005שונה],\u0006 \u0003ומעברא מיגלי אונסיה\u0004 \u0005[ומעבורת גלוי האונס שבה],\u0006 שיכול היה לשער מראש שיקרה לו דבר כזה, והיה עליו להתנות על כך, וכיון שלא התנה — אינו נחשב אונס.","ושואלים מצד אחר לעיקר הסברה: \u0003ולרב הונא\u0004 שאמר שבטלו זכויותיו, \u0003מכדי\u0004 \u0005[הרי]\u0006 עצם תנאי זה שהתנה שאם לא יבוא עד זמן מסויים יאבדו כל זכויותיו, הלא \u0003אסמכתא\u0004 \u0005[הסתמכות]\u0006 \u0003היא\u0004 בהנחה שהדבר לא יקויים. שבודאי לא גמר בדעתו לוותר על זכויותיו אלא סמך על כך שבודאי יחזור, \u0003ו\u0004כלל הוא בידינו ש\u0003אסמכתא\u0004 \u0005[הסתמכות]\u0006 \u0003לא קניא\u0004 \u0005[קונה]\u0006 ואפילו אם עשה אדם פעולת קנין לחזק את הדבר, לא גמר בדעתו להקנות! ודוחים: \u0003שאני הכא דמיתפסן זכותן\u0004 \u0005[שונה כאן שתפוסות זכויותיו]\u0006 בבית דין, וכיון שעשה כך ודאי גמר בדעתו.","ושואלים: \u0003והיכא דמיתפסין לאו אסמכתא היא\u0004 \u0005[ו\u0006האם ב\u0005מקום ש\u0006הן \u0005תפוסות\u0006 ביד אחר \u0005אין זו\u0006 נחשבת \u0005להסתמכות]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שפרע מקצת חובו, ו\u0004לשם בטחון \u0003השליש את שטרו,\u0004 כלומר, נתן שטרו לאדם שלישי, \u0003ואמר: אם אין אני נותן לו\u0004 את שארית החוב \u0003מכאן\u0004 (מהיום) ו\u0003עד שלשים יום — תן לו שטרו\u0004 ויגבה את הכל.","\u0003הגיע זמן ולא נתן, ר' יוסי אומר: יתן\u0004 השליש את השטר למלווה. \u0003ור' יהודה אומר: לא יתן. ואמר רב נחמן אמר רבה בר אבוה אמר רב: אין הלכה כר' יוסי\u0004 ש\u0003אמר\u0004 ש\u0003אסמכתא קניא\u0004 \u0005[הסתמכות קונה],\u0006 אלא הבטחה כגון זו אסמכתא היא ואינה קונה. הרי שאף במקרה שהיה השטר תפוס ביד אחר — מכל מקום אסמכתא אינה קונה!","ודוחים: \u0003שאני הכא דאמר לבטלן זכותיה\u0004 \u0005[שונה כאן ש\u0006הוא \u0005אומר\u0006 במפורש \u0005שייבטלו זכויותיו]\u0006 ואם כן גמר בליבו את הדבר.","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 בדברים אלה כך היא: בכלל \u0003אסמכתא קניא\u0004 \u0005[קונה]\u0006 שגם אם לא גמר את הקנין, אלא תלה את הדבר בתנאי כלשהו שאולי לא יתקיים — בכל זאת הוא מועיל. \u0003והוא דלא אניס\u0004 \u0005[וזהו\u0006 דווקא \u0005כשלא היה אנוס\u0006 בדבר\u0005]\u0006 אלא לא קיים התנאי מרצונו, \u0003והוא דקנו מיניה\u0004 \u0005[וזהו\u0006 דווקא \u0005שעשו עימו קנין]\u0006 על אסמכתא זו \u0003בבית דין חשוב,\u0004 אבל אין זה מועיל בהסכם בין אדם לחבירו שנעשה שלא בבית דין חשוב.","\u0003נודרין להרגין,\u0004 לאנשים שהם חשודים להרוג על עסקי ממון, או \u0003לחרמין,\u0004 לשודדים, או \u0003למוכסין\u0004 הרוצים לגבות ממנו מכס. ומותר לו, כדי להציל מידם את תבואתו, לידור נדר \u0003ש\u0004התבואה שבידו \u0003היא\u0004 של \u0003תרומה, אף על פי שאינו תרומה,\u0004 או \u0003שהן של בית המלך אף על פי שאינן של בית המלך.\u0004 שמכיון שעושה זאת כדי להציל עצמו או נכסיו, מותר לו לנדור נדר כגון זה, אף שאין הדבר נכון, ואין זה נחשב לנדר כלל. \u0003בית שמאי אומרים: בכל,\u0004 בכל דרך של נדר או איסור \u0003נודרין\u0004 להם נדר כזה שאינו מתכוון לו באמת,"],["\u0003חוץ מבשבועה,\u0004 שלא יאסור על עצמו בשבועה על מנת להטעותם, מפני שהשבועה חמורה. \u0003ובית הלל אומרים: אף בשבועה.\u0004","\u0003בית שמאי אומרים:\u0004 כשהוא מתדיין עם האיש שבא לשדוד אותו \u0003לא יפתח\u0004 (יתחיל) \u0003לו בנדר,\u0004 אלא אם כן השודד אינו מאמין לו, ואז מותר לו לידור כדי לחזק את דבריו, \u0003ובית הלל אומרים: אף יפתח לו. בית שמאי אומרים:\u0004 אינו נודר אלא \u0003במה שהוא מדירו\u0004 בלבד, ואינו מוסיף על כך. \u0003ובית הלל אומרים: אף במה שאינו מדירו.\u0004","ומסבירים, \u0003כיצד? אמר לו\u0004 השודד: \u0003אמור \"קונם אשתי נהנית לי\u0004 אם אין הדבר כן \u0003\", ואמר: \"קונם אשתי ובני נהנין לי\", בית שמאי אומרים: אשתו מותרת\u0004 שהרי המוכס תבע שיידור בדבר זה, \u0003ובניו\u0004 שהוא הוסיף מדעתו — \u0003אסורין. ובית הלל אומרים: אלו ואלו מותרין.\u0004","שנינו במשנה שנודרים למוכסים, ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: דינא דמלכותא דינא\u0004 \u0005[דין המלכות דין\u0006 הוא\u0005]\u0006 וצריך לקיים אותו! אם כן חייב אדם לשלם מכס שקבעה המלכות, וכיצד התירו חכמים לאדם אף לשקר על מנת שלא לשלם?","\u0003אמר רב חיננא אמר רב כהנא אמר שמואל:\u0004 כאן מדובר \u0003במוכס שאין לו קצבה,\u0004 שאינו נוטל סכום קצוב לפי הוראות המלכות, אלא מטיל מסים כפי ראות עיניו, וזה אינו דין המלכות. \u0003דבי\u0004 \u0005[\u0006חכם \u0005של בית\u0006 מדרשו של\u0005]\u0006 \u0003ר' ינאי אמר:\u0004 במשנה מדובר \u0003במוכס העומד מאליו,\u0004 שאינו ממונה כלל מטעם המלכות, אלא העמיד עצמו כמוכס.","שנינו במשנה: נודר \u0003שהן של בית המלך ואף על פי שאינן של בית המלך.\u0004 ושואלים: \u0003היכי נדר\u0004 \u0005[כיצד\u0006 הוא \u0005נודר]\u0006 נדר כזה? \u0003אמר רב עמרם אמר רב: באומר \"יאסרו פירות העולם עלי אם אינן של בית המלך\".\u0004","ושואלים: \u0003כיון דאמר\u0004 \u0005[שאומר]\u0006 \u0003\"יאסרו\"\u0004 הלא על ידי כך \u0003איתסרו עליה כל פירי עלמא\u0004 \u0005[נאסרו עליו כל פירות העולם]\u0006 כיון שאין זה נכון! ומשיבים: \u0003באומר \"\u0004ייאסרו עלי רק \u0003היום\".\u0004 ותוהים: \u0003אי דאמר\u0004 \u0005[אם שאומר]\u0006 \u0003\"היום\" לא מקבל מיניה\u0004 \u0005[יקבל ממנו]\u0006 ה\u0003מוכס\u0004 את הדבר כנדר. שהרי בעצם לא אסר על עצמו דבר חמור!","ומשיבים: \u0003באומר בלבו \"היום\", ומוציא בשפתיו סתם. ואף על גב דסבירא לן\u0004 \u0005[ואף על פי שסבורים אנו]\u0006 בדרך כלל להלכה ש\u0003דברים שבלב אינן\u0004 נחשבים כ\u0003דברים\u0004 ואין מתחשבים בהם — \u0003לגבי\u0004 \u0005[אצל]\u0006 \u0003אונסין שאני\u0004 \u0005[שונה]\u0006 הדבר והתירו לסמוך על תנאי שמוסיף בליבו כדי להתיר את נדרו.","שנינו במשנה ש\u0003בית שמאי אומרים: בכל\u0004 נודרים חוץ מבשבועה, ובית הלל מתירים אף בשבועה. \u0003בית שמאי אומרים:\u0004 נודר למוכס \u0003במה שהוא מדירו, ובית הלל אומרים: אף בשאינו מדירו. כיצד? אמר לו\u0004 המוכס: אמור \u0003\"קונם אשתי נהנית לי\", ואמר\u0004 הוא \u0003\"קונם אשתי ובני נהנין לי\". בית שמאי אומרים: אשתו מותרת ובניו אסורין, ובית הלל אומרים: אלו ואלו מותרין.\u0004","\u0003אמר רב הונא: תנא\u0004 \u0005[שנה\u0006 החכם\u0005],\u0006 \u0003בית שמאי אומרים: לא יפתח לו בשבועה, ובית הלל אומרים: אף יפתח לו בשבועה.\u0004 ותוהים: מדיוק הלשון משמע כי \u0003לבית שמאי\u0004 דווקא \u0003בשבועה\u0004 בלבד \u0003הוא\u0004 ש\u0003לא יפתח לו, הא\u0004 \u0005[הרי]\u0006 \u0003בנדר יפתח לו,\u0004 שמותר לו להתחיל ולידור מדעת עצמו. \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005],\u0006 \u0003בית שמאי אומרים: לא יפתח לו בנדר!\u0004","\u0003ותו\u0004 \u0005[ועוד]\u0006 ניתן לדייק: \u0003מיפתח\u0004 \u0005[לפתוח]\u0006 \u0003הוא\u0004 ש\u0003לא יפתח לו בשבועה\u0004 ומכאן אפשר להסיק: \u0003הא\u0004 \u0005[הרי]\u0006 שמכל מקום \u0003מידר נדר\u0004 \u0005[נודר\u0006 הוא\u0005]\u0006 \u0003בשבועה\u0004 אם המוכס עומד על כך. \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005],\u0006 \u0003בית שמאי אומרים: בכל נודרין חוץ מבשבועה,\u0004 משמע שאין נשבעים אפילו כשאינו פותח!","את הסתירה מיישבים: \u0003תנא מתניתין\u0004 \u0005[שנה\u0006 התנא את \u0005משנתנו]\u0006 \u0003בנדר\u0004 כדי \u0003להודיעך כחן\u0004 של \u0003בית שמאי\u0004 שאומרים שלכתחילה לא יפתח אפילו בנדר, \u0003תנא\u0004 \u0005[\u0006ו\u0005שנה]\u0006 ב\u0003ברייתא בשבועה, להודיעך כחן\u0004 של \u0003בית הלל\u0004 עד כמה הם מתירים שאף בשבועה יכול לפתוח, אבל באמת גם בנדר אין פותחים ובשבועה אין נודרים כלל לשיטת בית שמאי, ואין לדייק מלשון הברייתא.","\u0003רב אשי אמר,\u0004 כך יש לפתור את הסתירה, \u0003הכי קתני\u0004 \u0005[כך שנה]:\u0006 שאין המדובר בברייתא לענין נדר לאנסים ולמוכסים, אלא יש להבין את המחלוקת לענין אחר לגמרי, כי \u0003בית שמאי אומרים: אין שאלה בשבועה,\u0004 שמה שאמרו \"לא יפתח\" מתייחס לחכם הבא למצוא פתח להתיר את השבועה, \u0003ובית הלל אומרים: יש שאלה בשבועה.\u0004","נדר \u0003\"הרי נטיעות האלו קרבן אם אינן נקצצות\"\u0004 שהיתה רוח סערה, ונראה היה לו שכל הנטיעות עומדות להיקצץ, והקדישן אם לא יקצצו. או שראה אש הקרובה לשרוף את טליתו ואמר \u0003\"טלית זו קרבן אם אינה נשרפת\" —\u0004 קדושה חלה עליהן אם לא נקצצו או לא נשרפו, ו\u0003יש להן פדיון\u0004 כשאר הקדשים לבדק הבית. אבל אם אמר \u0003\"הרי נטיעות האלו קרבן עד שיקצצו\",\u0004 או אמר \u0003\"טלית זו קרבן עד שתשרף\" —\u0004"],["\u0003אין להם פדיון.\u0004","על לשון המשנה תוהים: מדוע נאמרו הדברים בסגנון \"יש להם פדיון\"? \u0003וליתני\u0004 \u0005[ושישנה]\u0006 \u0003\"קדושות ואין קדושות\"\u0004 שעיקר החידוש הוא שהן קדושות ואינן קדושות לגמרי! ומשיבים: \u0003איידי דבעי למיתנא סיפא\u0004 \u0005[מתוך שרצה לשנות בסוף]\u0006 את המקרה ש\u0003\"אין להם פדיון\"\u0004 שאי אפשר לאומרו בלשון \"אינן קדושות\", \u0003תנא נמי רישא\u0004 \u0005[שנה גם כן\u0006 ב\u0005תחילה]\u0006 בלשון \u0003\"יש להם פדיון\".\u0004","ומבררים: \u0003היכי\u0004 \u0005[כיצד]\u0006 \u0003נדר,\u0004 מה היתה בדיוק לשונו של הנודר? \u0003אמר אמימר: באומר \"\u0004הרי נטיעות האלו קרבן \u0003אם אינן נקצצות היום\" ועבר היום ולא נקצצו.\u0004 ושואלים: \u0003אם כן למה לי למימר\u0004 \u0005[לומר]\u0006 דבר זה, שחלה קדושה עליהם? \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שנדרו חל! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003כגון דאיכא זיקא נפישא\u0004 \u0005[שיש רוח גדולה]\u0006 והוא סבור שיישברו האילנות הללו.","ושואלים: \u0003והא קתני לה\u0004 \u0005[והרי שנה\u0006 את הדבר \u0005הזה]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003טלית, ו\u0004כי \u0003טלית לשריפה קיימא\u0004 \u0005[עומדת]?\u0006 ומשיבים: \u0003[אין]\u0004 \u0005[כן],\u0006 \u0003כגון דאיכא\u0004 \u0005[שיש]\u0006 \u0003דליקה. הכא נמי דאיכא זיקא נפישא\u0004 \u0005[כאן גם כן שיש רוח גדולה]\u0006 \u0003וסלקא דעתך\u0004 \u0005[והיה עולה על דעתנו]\u0006 \u0003דמסיק אדעתיה דלא מיתנצלן\u0004 \u0005[ש\u0006הוא \u0005מעלה על דעתו שאין\u0006 הן \u0005ניצלות]\u0006 \u0003ומשום הכי\u0004 \u0005[כך]\u0006 \u0003קא נדר\u0004 \u0005[הוא\u0006 \u0005נודר],\u0006 ויש מקום לומר שלא נתכוון בכל ליבו להקדישם, שהרי לא איכפת לו מה יקרה בסוף, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלמרות זאת יש בכך נדר.","שנינו במשנתנו שאם אמר \u0003\"הרי נטיעות האלו קרבן\u0004 עד שיקצצו\" — אין להן פדיון. ושואלים: \u0003ולעולם\u0004 אין להן פדיון? \u0003אמר בר פדא:\u0004 אם \u0003פדאן — חוזרות וקודשות, פדאן\u0004 שוב — \u0003חוזרות וקודשות, עד שיקצצו.\u0004 אם \u0003נקצצו — פודן פעם אחת ודיו. ועולא אמר: כיון שנקצצו — שוב אין פודן,\u0004 כלומר, אינו צריך לפדותן, שאינן קדושות עוד."],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב המנונא\u0004 לעולא: \u0003קדושה שבהן להיכן הלכה?\u0004 הרי הנטיעות הללו קדושות הן, וכיצד אפשר לומר שייצאו לחולין בלי פדיון כלל? \u0003ומה אילו אמר לאשה\u0004 בשעת קידושיה \u0003\"היום את אשתי ולמחר אי\u0004 (אין) \u0003את אשתי\" מי נפקא\u0004 \u0005[האם יוצאת]\u0006 ממנו למחר \u0003בלא גט?!\u0004 וכן במשנתנו, כיון שהקדיש את הנטיעות — כיצד קדושתן מתבטלת בלי פדיון?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מי קא מדמית\u0004 \u0005[האם מדמה אתה]\u0006 \u0003קדושת דמים\u0004 (הקדשת דבר על מנת להשתמש בדמיו לצורך ההקדש) \u0003לקדושת הגוף?\u0004 הלא \u0003קדושת דמים פקעה בכדי\u0004 \u0005[פוקעת בסתם],\u0006 שכיון שהיה הקדש זה על תנאי, כגון הקדשת האילנות עד שיקצצו, הרי כיון שהתקיים התנאי — בטלה הקדושה מהם, ואילו \u0003קדושת הגוף\u0004 שמקדש גופו של דבר, כגון שמקדש את האשה — \u0003לא פקעה בכדי\u0004 \u0005[פוקעת בסתם]\u0006 וצריך לעשות מעשה כדי להפקיע אותה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 וכי \u0003קדושת הגוף לא פקעה בכדי\u0004 \u0005[אינה פוקעת בסתם]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 אמר \u0003\"שור זה\u0004 יהיה \u0003עולה כל שלשים יום, ולאחר שלשים יום\u0004 יהיה \u0003שלמים\" — כל שלשים יום\u0004 הריהו \u0003עולה,\u0004 ו\u0003לאחר שלשים יום\u0004 הריהו \u0003שלמים.\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הרי \u0003קדושת הגוף נינהו\u0004 \u0005[הם]\u0006 שהקדישם לעולה, \u0003ופקעה בכדי\u0004 \u0005[ופוקעת בסתם]\u0006 לאחר שלושים יום, בלא מעשה!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 כגון ש\u0003אמר\u0004 שמקדיש \u0003לדמי\u0004 \u0005[לדמים].\u0006 שלא הקדיש את גוף הבהמה להיות קרבן עולה או לשלמים, אלא שאמר שדמיה יהיו עבור עולה או שלמים, ולא היתה בבהמה קדושת הגוף.","ומקשים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005סופה]\u0006 של אותה ברייתא: אם אמר \u0003\"לאחר שלשים יום\u0004 יהיה \u0003עולה, ומעכשיו\u0004 עד שלושים יום יהא \u0003שלמים\"\u0004 — דבריו קיימים. ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי פיסקה \u0003חדא\u0004 \u0005[אחת]\u0006 מדברת \u0003בקדושת הגוף, ו\u0004פיסקה \u0003חדא\u0004 \u0005[אחת]\u0006 מדברת \u0003בקדושת דמים —\u0004"],["\u0003היינו דאיצטריך ליה\u0004 \u0005[זהו\u0006 הטעם \u0005שהוצרך לו]\u0006 \u0003לתנא למיתנא תרתי\u0004 \u0005[לשנות שתים],\u0006 שתי פיסקות, כדי להדגיש שהלכה זו קיימת בכל מקרה. \u0003דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]:\u0006 \u0003קדושת הגוף לא פקעה בכדי\u0004 \u0005[בסתם]\u0006 אבל \u0003קדושת דמים פקעה בכדי\u0004 \u0005[סתם],\u0006 \u0003אמטו להכי\u0004 \u0005[משום כך]\u0006 \u0003תנא תרתי\u0004 \u0005[שנה שתים]\u0006 לומר שאין הבדל בין הדברים, ושתיהן פוקעות מעצמן.","\u0003אלא אי אמרת אידי ואידי\u0004 \u0005[אם אתה אומר\u0006 כי \u0005זו וזו],\u0006 שתי הפיסקאות, מדברות ב\u0003קדושת דמים, למה לי\u0004 אם כן \u0003למיתנא תרתי\u0004 \u0005[לשנות שתים]?\u0006 \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003יש לומר:\u0004 אם \u0003מקדושה חמורה\u0004 של עולה \u0003לקדושה קלה\u0004 של שלמים \u0003פקעה\u0004 הקדושה הראשונה, והבהמה נעשית כשלמים, \u0003מקדושה קלה\u0004 של שלמים \u0003לקדושה חמורה\u0004 של עולה \u0003צריכא למימר\u0004 \u0005[צריך לומר]?!\u0006","ומציעים: \u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא קושיה חמורה]\u0006 מן הברייתא על דברי \u0003בר פדא\u0004 ש\u0003אמר: לא פקעה קדושה בכדי\u0004 \u0005[בסתם]\u0006 אלא צריכה פדיון, ומן הברייתא רואים שאף קדושת הגוף פוקעת מעצמה?","\u0003אמר רב פפא: אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך בר פדא: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש לפרש את הברייתא: האומר \"שור זה לאחר שלושים יום עולה\" \u0003אם לא אמר \"מעכשיו שלמים\" — לאחר שלשים יום עולה הוי\u0004 \u0005[הוא\u0006 נעשה\u0005].\u0006 אבל כשאמר \"מעכשיו שלמים\" וחלה עליו קדושת שלמים — אינה פוקעת מעצמה.","\u0003מידי דהוה\u0004 \u0005[כפי שהוא]\u0006 הדין באיש \u0003האומר לאשה \"התקדשי לי\u0004 במעות אלו \u0003לאחר שלשים יום\"\u0004 ש\u0003מקודשת\u0004 האשה לאחר שלושים יום \u0003ואף על פי שנתעכלו\u0004 (כלו, התבזבזו) \u0003המעות\u0004 בינתיים, ואין הכסף קיים בשעת חלות הקידושין. וגם כאן יחול הקדש העולה לאחר שלושים יום.","ומקשים: אם כך היה המעשה, \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, ולמה הוצרך בכלל לשנות הלכה זו? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא למקרה \u0003דהדר ביה\u0004 \u0005[שחזר בו]\u0006 בתוך שלושים יום אלה, ורוצה שלא תחול קדושה כלל על בהמה זו, שלמרות שלא חלה הקדושה בפועל — אינו יכול לחזור.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שאשה שנתקדשה על מנת שיחולו הקידושין לאחר שלושים יום \u0003אינה חוזרת\u0004 שגם אם התחרטה בתוך שלושים יום אלה — חלו הקידושין. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003חוזרת, מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 שהרי אף בקידושין יכולה לחזור בה!","ומשיבים: \u0003אפילו למאן דאמר התם\u0004 \u0005[ל\u0006דעת \u0005מי שאומר שם,\u0006 בקידושין\u0005]\u0006 שאשה \u0003חוזרת\u0004 בה תוך שלושים יום, \u0003הכא שאני\u0004 \u0005[כאן שונה],\u0006 וטעמו של דבר — ש\u0003אמירתו לגבוה,\u0004 כלומר, כל דבר שהוא מקדיש לגבוה, לה', גם אם לא עשה מעשה אלא אמר זאת בפיו בלבד, דינו לענין תוקף הקנין \u0003כמסירתו להדיוט,\u0004 שגמר הקנין נעשה בזמן המסירה. שכיון שאין רשות הגבוה מתייחסת למקום מסויים, הרי באמירה בלבד דינו כאילו נגמר הקנין, ומשום כך ההקדש חל מיד. אבל בקידושי אשה אפשר לומר שהקידושין יחולו רק משעה שנגמר הקנין — בעוד שלושים יום.","מסופר: \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003ר' אבין ורב יצחק ברבי קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' ירמיה, וקא מנמנם\u0004 \u0005[והתנמנם]\u0006 \u0003ר' ירמיה,\u0004 ובעוד הוא מנמנם \u0003יתבי וקאמרי\u0004 \u0005[ישבו ואמרו]:\u0006 \u0003ל\u0004דעת \u0003בר פדא\u0004 ש\u0003אמר פדאן חוזרות וקודשות,\u0004"],["\u0003תפשוט\u0004 \u0005[תפתור]\u0006 מכאן את השאלה \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רב הושעיא: הנותן שתי פרוטות לאשה ואמר לה \"באחת\u0004 מהן \u0003התקדשי לי היום, ובאחת התקדשי לי לאחר שאגרשיך\",\u0004 שהסתפק רב אושעיא אם הקידושין השניים חלים כאשר הוא מגרשה. ומתוך דברי בר פדא יש לומר כי \u0003הכי נמי דהוו קידושי\u0004 \u0005[כך גם כן שהריהם קידושין],\u0006 שכיון שאמר שאם פדאן חוזרות וקודשות, משמע שלדעתו כאשר נגמרת קדושה ראשונה על ידי הפדיון, חלה מיד קדושה שניה. ואף כאן, לאחר שבטלו קידושין ראשונים על ידי הגט — חלו עליה קידושין שניים שקידשה מתחילה.","\u0003איתער בהו\u0004 \u0005[התעורר בהם]\u0006 \u0003ר' ירמיה\u0004 ששמע את דבריהם תוך כדי נמנום, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי קא מדמיתון\u0004 \u0005[מה אתם מדמים]\u0006 \u0003פדאן הוא לפדאום אחרים?\u0004 אין הדינים דומים, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: פדאן הוא — חוזרות וקדושות,\u0004 אבל אם \u0003פדאום אחרים\u0004 קודם שנקצצו — \u0003אין חוזרות וקדושות\u0004 כיון שהן בידי אחרים. \u0003ואשה\u0004 המתגרשת מבעלה \u0003כפדאוה אחרים דמיא\u0004 \u0005[נחשבת],\u0006 כי לאחר שנתגרשה האשה הריהי עומדת שוב לגמרי ברשות עצמה, וקידושין שניים אינם יכולים לחול אלא מדעתה, ואם אינה רוצה בכך — אינה מקודשת.","ומעירים: \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 \u0003אמר ר' אמי אמר ר' יוחנן: לא שנו אלא שפדאן הוא\u0004 עצמו, \u0003אבל פדאום אחרים — אין חוזרות וקדושות,\u0004 שאין הוא יכול להקדיש אותן לאחר שהיו כבר בידי אחרים, והדבר אינו תלוי עוד בדעתו.","\u0003הנודר מיורדי הים,\u0004 שאסר על עצמו ליהנות מהם — \u0003מותר ביושבי היבשה.\u0004 אבל אם נדר \u0003מיושבי היבשה — אסור\u0004 גם \u0003מיורדי הים,\u0004 ומדוע — \u0003שיורדי הים בכלל יושבי היבשה.\u0004 ומגדירים מי הם יורדי הים — \u0003לא כאלו שהולכים\u0004 (שנוסעים באניה) \u0003מעכו ליפו\u0004 שהיא נסיעה קצרה ואין הם נחשבים בכך \"יורדי ים\", \u0003אלא במי שדרכו לפרש,\u0004 לנסוע למרחקים גדולים, למדינות הים.","על המשפט האחרון של המשנה, בהגדרת יורדי הים נחלקו \u0003רב פפא ורב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא, חד מתני ארישא\u0004 \u0005[אחד\u0006 מהם \u0005היה שונה\u0006 את הדברים \u0005על ראשה\u0006 של המשנה\u0005]\u0006 \u0003וחד מתני אסיפא\u0004 \u0005[ואחד\u0006 מהם \u0005היה שונה על סופה].\u0006 ומסבירים: \u0003מאן דתני ארישא, מתני הכי\u0004 \u0005[מי ש\u0006היה \u0005שונה על ראשה, היה שונה כך]\u0006 ומסביר: \u0003הנודר מיורדי הים מותר ביושבי יבשה, הא\u0004 \u0005[הרי]\u0006 \u0003ביורדי הים — אסור, ולא כאלו\u0004"],["\u0003ההולכים מעכו ליפו, דהלין\u0004 \u0005[שאלה]\u0006 \u0003יושבי היבשה נינהו\u0004 \u0005[הם],\u0006 \u0003אלא\u0004 \"יורדי הים\" הכוונה \u0003ממי שדרכן לפרש.\u0004","\u0003ומאן דמתני אסיפא\u0004 \u0005[ומי שהיה שונה\u0006 את הדבר \u0005על הסוף\u0006 של המשנה\u0005]\u0006 \u0003מתני הכי\u0004 \u0005[היה שונה\u0006 ומבין \u0005כך]:\u0006 \u0003הנודר מיושבי יבשה אסור ביורדי הים, ולא באלו ההולכים מעכו ליפו בלבד\u0004 שהם בודאי אינם נחשבים יורדי ים, \u0003אלא אפילו במי שדרכו לפרש.\u0004 ומדוע אומרים שאף הם נחשבים ליושבי היבשה — \u0003הואיל וסופו ליבשה\u0004 הוא \u0003סליק\u0004 \u0005[עולה],\u0006 שאין אדם חי כל ימיו על הים אלא מגיע בסופו של דבר ליבשה, ולכן כל בני אדם נקראים \"יושבי יבשה\".","\u0003הנודר מרואי החמה — אסור אף בסומין\u0004 (עיוורים) אף שאינם רואים כלום, \u0003שלא נתכוון זה אלא למי שהחמה רואה אותן.\u0004","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר, הרי אמר \"רואי חמה\"! ומשיבים: \u0003מדלא קאמר\u0004 \u0005[מ\u0006פני \u0005שלא אמר]\u0006 \u0003\"מן הרואין\".\u0004 שאם היה אומר כן היתה כוונתו להוציא את העיוורים. אלא מה שאמר \"רואי חמה\" הרי זה \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003דגים ועוברים\u0004 שאינם נקראים \"רואי חמה\", לפי שאין החמה רואה אותם.","\u0003הנודר משחורי הראש,\u0004 אף ביטוי זה אין להבינו כמשמעו, אלא במשמעות רחבה יותר, ומשום כך \u0003אסור בקרחין,\u0004 אף על פי שאין להם שערות כלל, \u0003ו\u0004אסור אף ב\u0003בעלי שיבות\u0004 ששערותיהם לבנות. \u0003ומותר בנשים ובקטנים, שאין נקראין \"שחורי הראש\" אלא אנשים.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אנו אומרים שהביטוי \"שחורי הראש\" אין כוונתו להוציא מכלל זה קרחים — \u0003מדלא קאמר\u0004 \u0005[מ\u0006פני \u0005שלא אמר]\u0006 \u0003\"מבעלי שער\".\u0004","שנינו במשנה: \u0003ומותר בנשים ובקטנים שאין נקראין \"שחורי הראש\" אלא אנשים.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003אנשים זימנין דמיכסו רישייהו\u0004 \u0005[פעמים שמכסים\u0006 את \u0005ראשיהם]\u0006 \u0003וזימנין דמגלו רישייהו\u0004 \u0005[ופעמים שמגלים\u0006 את \u0005ראשיהם]\u0006 ולכן יש מקום לקרוא להם \"שחורי ראש\", שעל פי רוב השיער שלהם שחור. \u0003אבל נשים לעולם מיכסו\u0004 \u0005[תמיד\u0006 הן \u0005מכוסות\u0006 ראש\u0005],\u0006 \u0003וקטנים לעולם מיגלו\u0004 \u0005[תמיד\u0006 ראשם \u0005מגולה]\u0006 ולכן הביטוי \"שחורי הראש\" כוונתו לגברים, לאלה שלפעמים נראה שיער הראש שלהם.","\u0003הנודר מן הילודים\u0004 — מבינים שכוונתו לאלה שכבר נולדו ולכן \u0003מותר בנולדים\u0004 לאחר הזמן שנדר. אבל מי שנודר \u0003מן הנולדים — אסור\u0004 אף \u0003מן הילודים\u0004 כבר. \u0003ר' מאיר מתיר אף בילודים\u0004 בעבר, שלדעתו דיקדק הנודר לאסור עליו רק אלה שיוולדו. \u0003וחכמים אומרים: לא נתכוון זה\u0004 כשאמר \"נולדים\" \u0003אלא במי שדרכו להוולד,\u0004 ואין לדקדק בלשון זו, אלא ודאי התכוון לכל הנולדים בכל זמן.","על דברי ר' מאיר המתיר אף בילודים, שואלים: אם \u0003לר' מאיר\u0004 כשנדר מן הנולדים מותר \"אף בילודים\", אם כן משמע \u0003ולא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003נולדים\u0004 שנדר מהם במפורש, שהוא מותר בהם. \u0003אלא ממאן\u0004 \u0005[ממי\u0006 הוא\u0005]\u0006 \u0003אסור?\u0004 שהרי לפי זה אין בנדר הזה שום משמעות!","ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 היא \u0005שנויה],\u0006 כך צריך לשנותה: \u0003הנודר מן הילודים — מותר בנולדים, מן הנולדים — אסור בילודים. ר' מאיר אומר: אף הנודר מן הנולדים מותר בילודים, כי היכי\u0004 \u0005[כפי]\u0006 שה\u0003נודר מן הילודים מותר בנולדים,\u0004 שהוא מדקדק במשמעות הלשון כמו שאמרה הנודר.","על עצם החילוק בין הלשונות שבמשנתנו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: למימרא\u0004 \u0005[האם לומר]\u0006 מתוך הדברים הללו ש\u0003\"נולדים\" דמתיילדן משמע\u0004 \u0005[\u0006אלה \u0005שעומדים להיוולד משמעו]?\u0006 \u0003אלא מעתה\u0004 מה שנאמר בכתוב \u0003\"שני בניך הנולדים לך בארץ מצרים\"\u0004 (בראשית מח, ה) \u0003הכי נמי דאיתיילדן\u0004 \u0005[כך גם כן שעומדים להיוולד]\u0006 \u0003הוא?\u0004 והרי מדובר בכתוב באפרים ומנשה שכבר נולדו!","ודוחים: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 אתה רוצה לומר שהביטוי \"נולדים\" כוונתו אלה \u0003דיילידו\u0004 \u0005[ש\u0006כבר \u0005נולדו]\u0006 \u0003משמע, אלא מעתה\u0004 מה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"הנה בן נולד לבית דוד יאשיהו שמו\"\u0004 (מלכים א יג, ב) \u0003הכי נמי דהוה\u0004 \u0005[כך גם כן\u0006 כוונתו \u0005שהיה\u0006 כבר בעולם, שכבר נולד\u0005]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003עדיין מנשה לא בא\u0004 אז לעולם? כל שכן יאשיהו נכדו! \u0003אלא\u0004 לשון הכתוב \u0003משמע הכי\u0004 \u0005[כך]\u0006 \u0003ומשמע הכי\u0004 \u0005[כך],\u0006 שפעמים הכוונה לנולדים בעבר ופעמים הכוונה לעתידים להיוולד, \u0003ובנדרים הלך אחר לשון בני אדם,\u0004 ובלשון בני אדם \"נולדים\" פירושו אלה שעתידים להיוולד.","שנינו במשנתנו: \u0003וחכמים אומרים\u0004 שכאשר אומר \"נולדים\" אסור אפילו מן הילודים, ולדעתם \u0003לא נתכוין זה אלא\u0004 שנודר \u0003מ\u0004כל \u0003מי שדרכו להוולד.\u0004 ומעירים: \u0003לאפוקי מאי\u0004 \u0005[להוציא\u0006 את \u0005מה]\u0006 — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003דגים ועופות\u0004 שאינם נולדים אלא יוצאים מן הביצים, אבל \"נולדים\" משמעו כל אלה שנולדים מרחם אימם."],["\u0003הנודר משובתי שבת — אסור בישראל ואסור\u0004 גם \u0003בכותים\u0004 (שומרונים), שגם הם שומרים את השבת. הנודר \u0003מאוכלי שום\u0004 בלילי שבת — \u0003אסור בישראל ואסור בכותים,\u0004 שאף הם אוכלים שום בלילי שבת. ואולם אם נדר \u0003מעולי ירושלים — אסור בישראל ומותר בכותים,\u0004 שהרי הם אינם עולים לירושלים אלא להר גריזים.","על דברי המשנה \"הנודר משובתי שבת\" שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"שובתי שבת\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא \u0003ממקיימי שבת,\u0004 אלה שבפועל שומרים את השבת, \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע דווקא שנינו שאסור \u0003בכותים? אפילו\u0004 שאר \u0003גוים נמי\u0004 \u0005[גם כן]\u0006 יש ביניהם שומרי שבת. \u0003אלא\u0004 ודאי יש לומר שכוונתו שנודר \u0003מ\u0004מי ש\u0003מצווים על\u0004 שמירת \u0003השבת,\u0004 ולדעתו הכותים נחשבים כגרים גמורים, ומצווים על שמירת השבת.","אולם, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, אם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003\"מעולי ירושלים\" — אסור בישראל ומותר בכותים, אמאי\u0004 \u0005[מדוע]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מצווים נינהו\u0004 \u0005[הם]\u0006 לעלות לירושלים, כשאר הגרים!","\u0003אמר אביי: מצווה ועושה קתני\u0004 \u0005[שנה].\u0006 שהתנא סבור שכוונתו למי שמצווה מצוה מסויימת וגם עושה אותה. ולפי זה מובנת המשנה, \u0003בתרתי בבי קמייתא\u0004 \u0005[בשתי הפיסקות הראשונות]\u0006 בשביתת שבת ובאכילת שום, \u0003ישראל וכותים\u0004 בכלל, מפני שהם \u0003מצווין ועושין,\u0004 ואילו \u0003גוים ההוא דעבדי\u0004 \u0005[אלה שעושים]\u0006 דברים אלה — הרי \u0003עושין ואינם מצווין\u0004 על כך, ולכן מותר בהם, שאינם בכלל נדרו. ואילו \u0003בעולי ירושלים — ישראל מצווין ועושין,\u0004 ואילו \u0003כותים מצווין ואינם עושין,\u0004 ולכן מותר בהם.","אמר \u0003\"קונם שאיני נהנה לבני נח\" — מותר בישראל ואסור באומות העולם.\u0004","ושואלים: \u0003וישראל מי נפיק\u0004 \u0005[האם יוצאים]\u0006 \u0003מכלל בני נח?\u0004 הלא גם הם בכלל בני נח! ומשיבים: \u0003כיון דאיקדש\u0004 \u0005[שהוקדש]\u0006 \u0003אברהם\u0004 והתייחד, שייחשב למהות מיוחדת, \u0003איתקרו על שמיה\u0004 \u0005[נקראו על שמו]\u0006 כל צאצאיו, ושוב אינם נקראים סתם \"בני נח\".","האומר \u0003\"\u0004קונם \u0003שאיני נהנה לזרע אברהם\" — אסור בישראל ומותר באומות העולם.\u0004","על מה שאמרו במשנה \"ומותר באומות העולם\" שואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003ישמעאל\u0004 ובניו, שגם הם בכלל \"זרע אברהם\"! ומשיבים: \u0003\"כי ביצחק יקרא לך זרע\"\u0004 (בראשית כא, יב) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ומכאן שבני ישמעאל אינם נקראים \"זרע אברהם\". ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003עשו\u0004 ובניו, שגם הם בכלל \"זרע אברהם\", שהרי הם מבני יצחק! ומשיבים: \u0003\"ביצחק\u0004 יקרא לך זרע \u0003\"\u0004כוונתו \u0003ולא כל\u0004 זרעו של \u0003יצחק\u0004 אלא רק חלק מהם, שרק בני יעקב הם הנקראים \"זרע אברהם\" בשלימות.","הנודר \u0003\"שאיני נהנה מישראל\" — לוקח\u0004 (קונה) \u0003ביותר\u0004 מהמחיר המקובל \u0003ומוכר בפחות,\u0004 ונמצא שאינו נהנה מישראל. ואם נדר \u0003\"שישראל נהנין לי\",\u0004 כלומר, שאינם נהנים ממני — \u0003לוקח בפחות\u0004 מן המחיר \u0003ומוכר\u0004 להם \u0003ביותר\u0004 מן המחיר הרגיל, ונמצא שאין ישראל נהנים ממנו, \u0003ו\u0004אולם \u0003אין שומעין לו,\u0004 למעשה לא יסכימו בני אדם לנהוג בו כך, שיהיו הם מפסידים בכל משא ומתן עימו. אם נדר \u0003\"שאיני נהנה להן והן לי\"\u0004 במקרה זה — \u0003יהנה לאומות העולם\u0004 ולא יהנה מישראל, ואף לא יהנו ישראל ממנו.","\u0003אמר שמואל: הלוקח כלי מן האומן\u0004 כדי \u0003לבקרו\u0004 (לבדוק אותו) \u0003ונאנס בידו,\u0004 שנשבר הכלי באונס בתוך כדי כך — \u0003חייב\u0004 בתשלום. שכיון שהלוקח יכול בכל עת לגמור את הקנין, נמצא שבמשך זמן הבדיקה הריהו כשואל, שכל ההנאה היא שלו. \u0003אלמא קסבר\u0004 \u0005[מכאן ש\u0006הוא \u0005סבור]\u0006 שכל קניה \u0003הנאת לוקח היא,\u0004 שיש הנאה לקונה בעצם קנין של דבר יותר מאשר למוכר. וכיון שהלוקח הוא שנהנה — חייב באונסים.","ומעירים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003\"שאיני נהנה מישראל\" — מוכר בפחות.\u0004 ונדייק מכאן: \u0003אבל שוה בשוה\u0004 בדיוק במחיר הקצוב — \u0003לא. ו\u0004אולם \u0003אי\u0004 \u0005[אם]\u0006 \u0003הנאת לוקח היא\u0004 בעצם העיסקה שביניהם, שהלוקח נהנה מכך יותר מאשר המוכר — \u0003אפילו\u0004 היה מוכרו \u0003שוה בשוה\u0004 מותר הדבר, שהרי הנאת הלוקח היא ולא המוכר! ומשיבים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת \u0003בזבינא דרמי על אפיה\u0004 \u0005[במכר שמוטל על פניו],\u0006 כלומר, בסחורה שאין עליה קופצים והמוכר אינו יכול להיפטר ממנה, ובמקרה זה גם אם מכר שווה בשווה הרי זו הנאת המוכר.","על כך מקשים: \u0003אם כן אימא רישא\u0004 \u0005[אמור\u0006 את \u0005ראשה]\u0006 של אותה הלכה: \u0003לוקח ביותר.\u0004 ואם מדובר במשנה במקרה שהמוכר שמח למכור מדוע יקח דווקא ביותר? והרי יכול לקחת גם בשווה! \u0003ועוד, אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: אם נדר \u0003\"שישראל נהנין לי\" — [לוקח בפחות] ומוכר ביותר. ואי בזבינא דרמי על אפיה\u0004 \u0005[ואם\u0006 מדובר \u0005במכר שמוטל על פניו]\u0006 ואין עליו קופצים כלל — \u0003אפילו\u0004 מוכר \u0003שוה בשוה\u0004 יש בכך יותר הנאה לו מאשר לקונה!","ומשיבים: \u0003סיפא\u0004 \u0005[הסוף]\u0006 מדבר על מקרה הפוך: \u0003בזבינא חריפא\u0004 \u0005[במכר חריף]\u0006 שנמכר יפה ורבים הקופצים עליו, ואם אינו מוסיף אז על המחיר נמצא שהקונה נהנה מכך. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אם במקרה זה מדובר מדוע \u0003לוקח בפחות? אפילו שוה בשוה\u0004 יקנה! שהרי המכר נמכר היטב, ואין כאן הנאה למוכר אפילו במחירו הקצוב. \u0003אלא\u0004 צריך לומר כי"],["\u0003מתניתין בזבינא מיצעא\u0004 \u0005[משנתנו\u0006 עוסקת \u0005במכר ממוצע]\u0006 שאינו גרוע ובלתי נמכר, וגם לא במכר חריף שהכל להוטים אחריו, אלא במכר רגיל שכאשר נמכר במחיר הקצוב אין לומר שהמוכר או הקונה נהנה יותר, ומשום כך המודר הנאה צריך לפחות מן המחיר כאשר הוא מוכר, ולהוסיף עליו כאשר הוא קונה. \u0003ו\u0004דבריו של \u0003שמואל\u0004 הם \u0003בזבינא חריפא\u0004 \u0005[במכר חריף]\u0006 שאז הקניה במחיר השווה נחשבת כהנאת הלוקח.","ומעירים: \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל\u0004 שלקיחת דבר, כאשר מתנה הקונה שיוכל להחזירו נחשבת כהשאלה. ששנינו: \u0003הלוקח\u0004 (הקונה) \u0003כלים מן התגר\u0004 (הסוחר) על מנת \u0003לשגרן\u0004 (לשלוח אותם) \u0003לבית חמיו\u0004 (אבי אשתו) כמתנה, \u0003ואמר לו\u0004 לתגר: \u0003אם מקבלין אותן ממני — אני נותן לך דמיהם, ואם לאו\u0004 שלא ירצו במתנה זו — \u0003אני נותן לך לפי טובת הנאה שבהן,\u0004 כלומר, אשלם משהו עבור ההנאה שהיתה לי במה שהראיתי לבית חותני שאני רוצה לכבדם, אם \u0003נאנסו בהליכה,\u0004 שקרה אונס לכלים ונשברו בזמן שהוליך אותם לבית חותנו — \u0003חייב\u0004 הלוקח, מפני שהוא כשואל.","אבל אם נאנסו \u0003ב\u0004דרך \u0003חזרה\u0004 שלא רצו את הכלים הללו בבית חותנו, והחזירם למוכר — \u0003פטור, מפני שהוא כנושא שכר.\u0004 שכיון שהחליט שלא לקנותם, ושוב אינו נהנה מהם — אינו נחשב עוד כשואל אלא כשומר שכר על הכלים הללו, ושומר שכר פטור מן האונסין.","מסופר: \u0003ההוא ספסירא דשקל חמרא לזבוני\u0004 \u0005[סרסור,\u0006 מתווך \u0005אחד שלקח חמור למכור\u0006 אותו\u0005]\u0006 \u0003ולא איזבן\u0004 \u0005[נמכר].\u0006 \u0003בהדי דהדר\u0004 \u0005[בזמן שחזר]\u0006 בדרכו להחזיר את החמור לבעליו \u0003איתניס חמרא\u0004 \u0005[קרה אונס לחמור],\u0006 \u0003חייביה\u0004 \u0005[חייב אותו]\u0006 \u0003רב נחמן לשלומי\u0004 \u0005[לשלם].\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 מברייתא זו: \u0003נאנסו בהליכה — חייב, בחזרה — פטור.\u0004 והרי כאן אירע האונס בזמן החזרה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003חזרה דספסירא\u0004 \u0005[של הסרסור]\u0006 — \u0003הולכה היא,\u0004 ואינו נחשב מוחזר עד שיתננו ממש לבעליו. ומדוע — \u0003דאילו משכח לזבוני\u0004 \u0005[שאם היה מוצא\u0006 אפשרות \u0005למכור]\u0006 את החמור \u0003אפילו אבבא דביתיה\u0004 \u0005[על פתח ביתו]\u0006 של בעל החמור \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא מזבין ליה\u0004 \u0005[היה מוכר אותו]?\u0006 ואם כן מבחינתו אין משמעות לדרך חזרה. מה שאין כן במי שהוליך מתנה לאדם מסויים ולא קיבלו, מאז בטלה המכירה ומוטלת עליו רק שמירת החפץ עד שיחזור לבעליו.","הנודר \u0003\"קונם שאני נהנה לערלים\" — מותר בערלי ישראל\u0004 שאינם נקראים \"ערלים\", \u0003ואסור במולי אומות העולם\u0004 (גויים נימולים).","ולהיפך, אם אמר \u0003\"שאני נהנה למולים\" — אסור\u0004 אפילו \u0003בערלי ישראל, ומותר במולי אומות העולם. שאין הערלה קרויה אלא לשם אומות העולם, שנאמר: \"כי כל הגוים ערלים וכל בית ישראל ערלי לב\"\u0004 (ירמיה ט, כה). \u0003ואומר: \"והיה הפלשתי הערל הזה\"\u0004 (שמואל א יז, לו). \u0003ואומר \"פן תשמחנה בנות פלשתים פן תעלזנה בנות הערלים\"\u0004 (שמואל ב א, כ). משמע שסתם גויים נקראים ערלים, ואין מבחינים אם יש ביניהם גם נימולים.","\u0003ר' אלעזר בן עזריה אומר: מאוסה היא הערלה שנתגנו בה רשעים שנאמר: \"כי כל הגוים ערלים\"\u0004 (ירמיה ט, כה), משמע שיש בערלות צד גנאי. \u0003ר' ישמעאל אומר: גדולה\u0004 היא ה\u0003מילה ש\u0004כן \u0003נכרתו עליה שלש עשרה בריתות,\u0004 ששלוש עשרה פעמים כתובה המלה \"ברית\" בפרשת המילה (בראשית פרק יז).","\u0003ר' יוסי אומר: גדולה מילה שדוחה את השבת\u0004 ה\u0003חמורה.\u0004 שאם חל יום השמיני ללידת הבן בשבת — נימול בשבת, אף שבכך דוחים את השבת בעשיית מלאכה.","\u0003ר' יהושע בן קרחה אומר: גדולה מילה,\u0004 וראיה לדבר — \u0003שלא נתלה\u0004 (נתעכב העונש) \u0003לו למשה הצדיק עליה\u0004 אפילו \u0003מלא שעה,\u0004 אלא מיד כשהיה יכול למול ולא מל נענש על כך (ראה שמות ד, כד-כו).","\u0003ר' נחמיה אומר: גדולה מילה שדוחה את הנגעים.\u0004 שאם היה נגע צרעת בעורלתו של התינוק, אף שאסור לחתוך את הנגע, בזמן שיש מצות מילה — מותר. \u0003רבי אומר: גדולה מילה, שכל המצות שעשה אברהם אבינו לא נקרא שלם עד שמל, שנאמר: \"התהלך לפני והיה תמים\"\u0004 (בראשית יז, א), שאז ניתנה לו מצוה זו.","\u0003דבר אחר: גדולה מילה שאלמלא היא לא ברא הקדוש ברוך הוא את עולמו, שנאמר: \"כה אמר ה' אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי\"\u0004 (ירמיה לג, כה), והברית שקיימת ביום ובלילה הרי היא ברית המילה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהושע בן קרחה אומר: גדולה מילה, שכל זכיות שעשה משה רבינו לא עמדו לו כשנתרשל מן המילה, שנאמר: \"ויפגשהו ה' ויבקש המיתו\"\u0004 (שמות ד, כד).","\u0003אמר רבי: חס ושלום שמשה רבינו נתרשל מן המילה, אלא כך אמר:\u0004 אם \u0003אמול\u0004 את הילד עכשיו \u0003ואצא\u0004 לדרך — \u0003סכנה היא\u0004 לילד, \u0003שנאמר: \"ויהי ביום השלישי בהיותם כואבים\" וגו'\u0004 (בראשית לד, כה), משמע שכאב המילה נמשך כמה ימים, ועלול הילד להסתכן. ואם \u0003אמול\u0004 מיד \u0003ואשהא שלשה ימים\u0004 ורק אחר כך אצא לדרך — הלא \u0003הקדוש ברוך הוא אמר לי \"לך שב מצרים\"\u0004 (שמות ד, יט) מיד. ומפני טעם זה לא מל, ואם כן לא היתה בכך התרשלות. \u0003אלא\u0004 לפי זה \u0003מפני מה נענש משה —\u0004"],["\u0003מפני שנתעסק במלון תחלה\u0004 ולא נפנה מיד למצות המילה, \u0003שנאמר \"ויהי בדרך במלון\"\u0004 (שמות ד, כד).","\u0003רבן שמעון בן גמליאל אומר: לא למשה רבינו בקש שטן להרוג אלא לאותו תינוק\u0004 שלא נימול, \u0003שנאמר: \"כי חתן דמים אתה לי\"\u0004 (שמות ד, כה), \u0003צא וראה מי קרוי חתן\u0004 במקרה זה — \u0003הוי אומר זה התינוק,\u0004 שהרי הוא שנכנס על ידי המילה לברית אברהם.","\u0003דרש ר' יהודה בר ביזנא: בשעה שנתרשל משה רבינו מן המילה באו\u0004 מלאכי החבלה \u0003\"אף\" ו\"חימה\", ובלעוהו, ולא שיירו ממנו אלא רגליו. מיד \"ותקח צפרה צר ותכרת את ערלת בנה\"\u0004 (שמות ד, כה), \u0003מיד \"וירף ממנו\"\u0004 (שמות ד, כו).","\u0003באותה שעה ביקש\u0004 (רצה) \u0003משה רבינו להורגן, שנאמר: \"הרף מאף ועזב חמה\"\u0004 (תהלים לז, ח), משמע שרצה לפגוע בהם. \u0003ויש אומרים: לחימה הרגו, שנאמר: \"חמה אין לי\"\u0004 (ישעיה כז, ד). ושואלים: איך אפשר לומר שנהרג חימה, \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בדברי משה עצמו מאוחר הרבה יותר: \u0003\"כי יגרתי מפני האף והחמה\"\u0004 (דברים ט, יט)! ומשיבים: \u0003תרי\u0004 \u0005[שני]\u0006 סוגים של \u0003חימה הוו\u0004 \u0005[הם].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003גונדא\u0004 \u0005[הגדוד,\u0006 הצבא\u0005]\u0006 של \u0003חימה\u0004 נותר, ולא חימה עצמו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003רבי אומר: גדולה מילה, שאין לך מי שנתעסק במצות כאברהם אבינו, ולא נקרא תמים אלא על שם\u0004 מצות \u0003מילה, שנאמר: \"התהלך לפני והיה תמים\"\u0004 (בראשית יז, א), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ואתנה בריתי ביני ובינך\"\u0004 (דברים ט, ב).","\u0003דבר אחר: גדולה מילה, ששקולה כנגד כל המצות שבתורה, שנאמר: \"כי על פי הדברים האלה\u0004 כרתי אתך ברית ואת ישראל\u0003\"\u0004 (שמות לד, כז). \u0003דבר אחר: גדולה מילה, שאילמלא מילה לא נתקיימו שמים וארץ, שנאמר: \"אם לא בריתי יומם ולילה\u0004 חוקות שמים וארץ לא שמתי\u0003\"\u0004 (ירמיה לג, כה), וברית שקיימת תמיד, ביום ובלילה, היא ברית המילה.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 אימרה זו על דברי \u0003ר' אליעזר.\u0004 ש\u0003אמר ר' אליעזר: גדולה תורה, שאילמלא תורה לא נתקיימו שמים וארץ, שנאמר: \"אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי\" וגו'.\u0004 ולדעתו הברית שאותה מקיימים יומם ולילה היא התורה, כאמור: \"והגית בו יומם ולילה\" (יהושע א, ח).","\u0003אמר רב יהודה אמר רב: בשעה\u0004 ש\u0003אמר לו הקדוש ברוך הוא לאברהם אבינו \"התהלך לפני והיה תמים\" אחזתו רעדה. אמר: שמא יש בי דבר מגונה\u0004 שעשיתי ולכן אינני נקרא תמים. \u0003כיון\u0004 ש\u0003אמר לו \"ואתנה בריתי ביני ובינך\"\u0004 (יהושע א, ב) \u0003נתקררה\u0004 (נחה) \u0003דעתו,\u0004 שהבין שהכוונה היא להסרת הערלה, והיא הפוגמת.","נאמר שם: \u0003\"ויוצא אתו החוצה\"\u0004 (יהושע טו, ה), \u0003אמר\u0004 אברהם \u0003לפניו: רבונו של עולם, הסתכלתי במזל שלי ואין לי אלא בן אחד\u0004 וכבר נולד לי בן, והוא ישמעאל. \u0003אמר לו: צא מאיצטגנינות\u0004 (ראיה בכוכבים) \u0003שלך, אין מזל לישראל,\u0004 כלומר, אין המזל קובע לגבי ישראל.","\u0003אמר ר' יצחק: כל המתמים עצמו\u0004 (נוהג בתמימות) — \u0003הקדוש ברוך הוא מתמים עמו\u0004 (נוהג עימו בשלימות), \u0003שנאמר: \"עם חסיד תתחסד עם גבור תמים תתמם\"\u0004 (שמואל ב כב, כו).","\u0003אמר ר' הושעיא: כל המתמים עצמו — שעה\u0004 (הזמן, הגורל) \u0003עומדת לו\u0004 והוא מצליח, \u0003שנאמר: \"התהלך לפני והיה תמים\", וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"והיית לאב המון גוים\"\u0004 (בראשית יז, ד).","\u0003אמר רבי: כל המנחש\u0004 שמנסה לנחש ולמצוא סימנים — \u0003לו נחש,\u0004 הניחוש פוגע בו, \u0003שנאמר: \"כי לא נחש ביעקב\"\u0004 (במדבר כג, כג). ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בלמ\"ד אל\"ף כתיב\u0004 \u0005[נאמר]\u0006 שלא נאמר \"כי לו נחש\" כפי שדרשנו, אלא \"כי לא נחש\"! \u0003אלא משום מדה כנגד מדה,\u0004 כיון שהוא מנחש — לכן הדבר פוגע בו.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003אהבה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' זירא: כל אדם שאינו מנחש מכניסין אותו\u0004 קרוב לקדוש ברוך הוא, \u0003במחיצה\u0004 (במקום) \u0003שאפילו מלאכי השרת אין יכולין ליכנס בתוכה, שנאמר: \"כי לא נחש ביעקב ולא קסם בישראל\u0004 כעת יאמר ליעקב ולישראל מה פעל אל\u0003\"\u0004 (במדבר כג, כג) כלומר, לישראל נאמרים דברים שאפילו המלאכים אינם יודעים, מפני שישראל קרובים יותר לה' מן המלאכים.","\u0003אמר ר' אבהו אמר ר' אלעזר: מפני מה נענש אברהם אבינו ונשתעבדו בניו למצרים מאתים ועשר שנים — מפני שעשה אנגרייא\u0004 (שעבוד) \u0003בתלמידי חכמים, שנאמר: \"וירק את חניכיו ילידי ביתו\"\u0004 (בראשית יד, יד), וחניכיו הללו היו תלמידיו בתורה ולקח אותם למלחמה.","\u0003ושמואל אמר: מפני שהפריז\u0004 (בחן ובדק) \u0003על מדותיו של הקדוש ברוך הוא, שנאמר: \"במה אדע כי אירשנה\"\u0004 (בראשית טו, ח). \u0003ור' יוחנן אמר:\u0004 נענש משום \u0003שהפריש\u0004 (הרחיק) \u0003בני אדם מלהכנס תחת כנפי השכינה, שנאמר\u0004 שאמר לו מלך סדום: \u0003\"תן לי הנפש והרכש קח לך\"\u0004 (בראשית יד, כא) ואברהם סירב לקבל דבר והחזיר הכל, ואם לא היה שומע בקול מלך סדום ומשאיר הנפש אצלו — היה מקרב את השבויים תחת כנפי השכינה.","נאמר: \u0003\"וירק את חניכיו ילידי ביתו\"\u0004 (בראשית יד, יד), \u0003רב אמר: שהוריקן בתורה,\u0004 שלימדם תורה כמי ששופך דבר על מישהו. \u0003ושמואל אמר: שהוריקן בזהב,\u0004 שנתן להם ממון רב כדי שילכו עימו למלחמה.","נאמר שלקח \u0003\"שמנה עשר ושלש מאות\"\u0004 (בראשית יד, יד), \u0003אמר ר' אמי בר אבא: אליעזר\u0004 שקול \u0003כנגד כולם. איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003אליעזר\u0004 בלבד \u0003הוא\u0004 שנרמז כאן, \u0003דחושבניה הכי הוי\u0004 \u0005[שחשבונו כך הוא],\u0006 שגימטריה של \"אליעזר\" היא שלוש מאות ושמונה עשרה.","\u0003ואמר ר' אמי בר אבא: בן שלש שנים הכיר אברהם את בוראו, שנאמר: \"עקב אשר שמע אברהם בקלי\"\u0004 (בראשית כו, ה) — \"עקב\" \u0003חושבניה\u0004 \u0005[חשבונו]\u0006 בגימטריה הוא \u0003מאה ושבעין ותרין\u0004 \u0005[מאה שבעים ושתים]\u0006 וכל שנותיו של אברהם היו מאה שבעים וחמש, ו\"עקב\" שנים שמר את חוקותיו של הקדוש ברוך הוא. משמע שתחילת הכרתו את הבורא היתה בגיל שלוש.","\u0003ו\u0004אגב העיסוק בדברים שעל פי גימטריה מביאים עוד מה ש\u0003אמר רמי בר אבא\u0004 בדרך דומה:"],["\u0003\"השטן\" בחושבניה\u0004 \u0005[בחשבונו\u0006 בגימטריה\u0005]\u0006 \u0003תלת מאה ושיתין\u0004 \u0005[שלוש מאות ושישים]\u0006 \u0003וארבעה\u0004 כנגד ימות השנה, חוץ מיום הכיפורים שאין הוא שולט בו. \u0003ואמר רמי בר אבא: כתיב\u0004 \u0005[נאמר]\u0006 בתחילה השם \u0003\"אברם\", וכתיב\u0004 \u0005[ונאמר]\u0006 לאחר שנצטווה על המילה ששינה ה' את שמו ל\u0003\"אברהם\"\u0004 (בראשית יז, ה). \u0003בתחלה המליכו הקדוש ברוך הוא על מאתים וארבעים ושלשה אברים\u0004 כגימטריה של \"אברם\", \u0003ולבסוף\u0004 כשנימול \u0003המליכו על מאתים וארבעים ושמונה אברים\u0004 כגימטריה של \"אברהם\",","\u0003אלו הן\u0004 האברים הנוספים: \u0003שתי עינים, ושתי אזנים, וראש הגוייה\u0004 (אבר המין), שיהא לו שלטון גמור עליהם ולא יפעלו אלא לפי רצונו בלבד.","\u0003ואמר רמי בר אבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"עיר קטנה ואנשים\u0004 בה מעט ובא אליה מלך גדול וסבב אותה ובנה עליה מצודים גדולים. ומצא בה איש מסכן חכם ומלט הוא את העיר בחכמתו, ואדם לא זכר את האיש המסכן ההוא\u0003\"\u0004 (קהלת ט, יד-טו). \u0003\"עיר קטנה\" — זה הגוף, \"ואנשים בה מעט\" — אלו אברים, \"ובא אליה מלך גדול וסבב אתה\" — זה יצר הרע, \"ובנה עליה מצודים וחרמים\" — אלו עונות,\u0004","\u0003\"ומצא בה איש מסכן וחכם\" — זה יצר טוב, \"ומלט הוא את העיר בחכמתו\" — זו תשובה ומעשים טובים\u0004 שהיצר הטוב גורם לאדם לעשותם. \u0003\"ואדם לא זכר את האיש המסכן ההוא\"\u0004 כוונתו ש\u0003בשעת\u0004 התגברות \u0003יצר הרע לית דמדכר ליה\u0004 \u0005[אין\u0006 מי \u0005שזוכר אותו]\u0006 \u0003ליצר טוב.\u0004 ובאותו אופן פירשו את הפסוק \u0003\"החכמה תעז לחכם מעשרה שליטים\u0004 אשר היו בעיר\u0003\"\u0004 (קהלת ז, יט). \u0003\"החכמה תעז לחכם\" — זו תשובה ומעשים טובים, \"מעשרה שליטים\" —\u0004 אלו \u0003שתי עינים, ושתי אזנים, ושתי ידים, ושתי רגלים, וראש הגוייה, ופה,\u0004 שהם החלקים החשובים שבהם פועל ונפעל האדם. \u0003אמר ר' זכריה משום\u0004 (בשם) \u0003ר' ישמעאל: ביקש הקדוש ברוך הוא להוציא\u0004 (להמשיך) \u0003כהונה משם,\u0004 כלומר, שגם בניו יהיו כהנים, \u0003שנאמר\u0004 בשם עצמו: \u0003\"והוא כהן לאל עליון\"\u0004 (בראשית יד, יח). \u0003כיון שהקדים\u0004 שם \u0003ברכת אברהם לברכת המקום — הוציאה\u0004 את הכהונה \u0003מאברהם,\u0004 שיהיו בני אברהם כהנים ולא בני שם.","","","ומנין שהקדים ברכת עבד לברכת הרב — \u0003שנאמר: \"ויברכהו ויאמר ברוך אברם לאל עליון קנה שמים וארץ וברוך אל עליון\"\u0004 (בראשית יט-כ). \u0003אמר לו אברהם: וכי מקדימין ברכת עבד לברכת קונו?\u0004 היית צריך לברך קודם את הקדוש ברוך הוא! \u0003מיד נתנה\u0004 הקדוש ברוך הוא את הכהונה \u0003לאברהם, שנאמר: \"נאם ה' לאדני שב לימיני עד אשית איביך הדם לרגליך\"\u0004 (תהלים קי, א), \u0003ובתריה כתיב\u0004 \u0005[ואחריו נאמר]:\u0006 \u0003\"נשבע ה' ולא ינחם אתה כהן לעולם על דברתי מלכי צדק\"\u0004 (תהלים קי, ד). כלומר, \u0003על\u0004 (בגלל) \u0003דיבורו\u0004 (\"דברתי\") \u0003של מלכי צדק\u0004 שדיבר שלא כהוגן, לכן יהיה זרע אברהם כהן לעולם לה'.","ומעירים: \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]\u0006 בדקדוק לשון הכתוב על מלכי צדק \u0003\"והוא כהן לאל עליון\"\u0004 (בראשית יד, יח) להדגיש: \u0003הוא כהן, ואין זרעו כהן.\u0004","","\u0003אין\u0004 הבדל בהלכה \u0003בין המודר הנאה מחבירו\u0004 שנאסר בנדר שלא להנות מחבירו כלל, \u0003למודר הימנו\u0004 רק מ\u0003מאכל, אלא\u0004 לענין \u0003דריסת הרגל\u0004 בחצירו ובביתו, \u0003ו\u0004שימוש ב\u0003כלים שאין עושין בהם אוכל נפש.\u0004","ולכן \u0003המודר מאכל מחבירו לא ישאילנו\u0004 חבירו גם כלים שעושים בהם מאכל, כגון \u0003נפה וכברה וריחים ותנור, אבל משאיל לו חלוק וטבעת וטלית ונזמים,\u0004 שאינם כלים למאכל, ואילו המודר הנאה אסור להשאיל גם כלים אלה.","\u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 ששנה משנה זו? \u0003אמר רב אדא בר אהבה:\u0004 שיטת \u0003ר' אליעזר היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' אליעזר אומר: אפילו ויתור,\u0004 דבר שכרגיל אנשים מוותרים עליו לאחרים ואין מקפידים בו, \u0003אסור במודר הנאה.\u0004 ולכן נאמר במשנה שהמודר הנאה אסור אפילו לדרוס בחצירו של חבירו, למרות שאין זה דבר שאנשים מקפידים עליו כרגיל.","שנינו במשנה: \u0003המודר מאכל מחבירו לא ישאילנו\u0004 נפה וכברה \u0003וכו'.\u0004"],["ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מן מאכל נדר\u0004 ולא מדבר אחר! \u0003אמר ר' שמעון בן לקיש: באומר \"הנאת מאכלך עלי\",\u0004 ובכלל זה כל הנאה השייכת למאכל.","ומקשים על כך: \u0003אימא\u0004 \u0005[אמור]\u0006 שלשון נדר זו כוונתה \u0003שלא ילעוס חיטין\u0004 של המודר \u0003ויתן על מכתו\u0004 לרפואה, שהיא הנאה שבאה מכוח מאכל, אבל לא לדברים המביאים לידי מאכל! \u0003אמר רבא: באומר \"הנאה המביאה לידי מאכלך עלי\",\u0004 כלומר, אסר עצמו מכל דבר שמביא לידי אכילה.","\u0003אמר רב פפא:\u0004 לקחת מן המודר \u0003שק להביא פירות,\u0004 או \u0003חמור להביא עליו פירות, ואפילו צנא בעלמא\u0004 \u0005[סל בלבד],\u0006 מכל מקום \u0003הנאה המביאה לידי מאכל הוא\u0004 ואסורה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם רוצה הנודר הנאת מאכל לשאול מהמודר ממנו \u0003סוס לרכוב עליו וטבעת ליראות בה\u0004 כאשר הוא הולך למשתה, כדי שייראה כעשיר, \u0003מהו?\u0004 האם נאמר שאסור, משום שעל ידי כך גורם בעקיפין שיתנו לו אוכל קודם לאחרים, או מאכלים טובים יותר, והרי זו הנאה המביאה לידי מאכל? וכן \u0003מיפסק ומיזל בארעיה\u0004 \u0005[לחתוך,\u0006 לקצר דרכו \u0005וללכת\u0006 דרך \u0005הקרקע שלו]\u0006 ועל ידי כך ממהר לחזור לביתו לאכול, \u0003מאי\u0004 \u0005[מהו]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003אבל משאיל לו\u0004 למודר ממנו הנאת מאכל \u0003חלוק וטלית נזמים וטבעות.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שלא ליראות בהן,\u0004 שאינו הולך עימם בין הבריות ואין לו הנאת מאכל על ידי כך, וכי \u0003צריכא למימר\u0004 \u0005[צריך לומר]\u0006 שמותר? הלא רק ממאכל נדר ממנו! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003אפילו\u0004 כששואל כדי \u0003ליראות בהן, וקתני\u0004 \u0005[ושנה]\u0006 \u0003\"משאילו\"!\u0004","ודוחים: \u0003לא, לעולם\u0004 אפשר לומר שמדובר במשנה שלקח על מנת \u0003שלא ליראות\u0004 בהן, \u0003ואיידי דקתני רישא\u0004 \u0005[ומתוך ששנה בתחילה]\u0006 \u0003\"לא ישאילנו\"\u0004 על מנת להגדיר מה הם הדברים האסורים בהשאלה, \u0003תנא סיפא\u0004 \u0005[שנה בסוף]\u0006 \u0003\"משאילו\",\u0004 אף שאין בכך שום חידוש. ושאלת רב פפא נשארה איפוא ללא פתרון.","\u0003וכל דבר שאין עושין בו אוכל נפש,\u0004 אם היה זה \u0003מקום שמשכירין\u0004 אנשים לחבריהם חפצים \u0003כיוצא בהן\u0004 תמורת תשלום — \u0003אסור\u0004 למודר הנאת מאכל לשאול אותו מן המדיר, שהרי מרוויח כסף על ידי השאלה זו, ונמצא שבאופן עקיף מביא לידי מאכל.","מדברי המשנה מדייקים: \u0003מכלל\u0004 הדברים במשנתנו עולה \u0003דרישא\u0004 \u0005[שבראש,\u0006 בתחילת המשנה\u0005]\u0006 לגבי איסורו של המודר בכלים שעושים בהם אוכל נפש, כגון נפה וכברה, מדובר \u0003אף על פי שאין משכירין\u0004 כיוצא בהם אלא הכל נוהגים להשאילם בחינם. ונברר \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר רב אדא בר אהבה: ר' אליעזר היא,\u0004 הסבור שאפילו ויתור אסור בנדרים. שאף דברים שאנשים עושים כרגיל ואינם מקבלים עליהם שכר — מכל מקום אסורים במודר מחבירו.","\u0003המודר הנאה\u0004 שלא יהנה \u0003מחבירו\u0004 — אם רצה חבירו \u0003שוקל לו את שקלו,\u0004 משלם עבור המודר את מחצית השקל למקדש, \u0003ופורע\u0004 לו \u0003את חובו, ומחזיר לו את אבידתו\u0004 ואין זה נקרא שמהנה אותו. \u0003מקום שנוטלין עליה\u0004 על השבת אבידה \u0003שכר — תפול\u0004 (תינתן) \u0003הנאה\u0004 זו שמקבל עבור ההשבה \u0003להקדש.\u0004","ממה שהתירה המשנה לשלם חובות שונים עבור המודר בהנאה מסיקים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 שכל התשלומים הללו נחשבים כאילו היו \u0003אברוחי ארי בעלמא\u0004 \u0005[הברחת אריה בלבד]\u0006 \u0003הוא, ושרי\u0004 \u0005[ומותרת],\u0006 כלומר, שאין מחשיבים זאת כנתינת דבר, אלא כאילו מסלק ממנו היזק (\"אריה\") שעתיד לקרות לו, ודבר כזה אינו נקרא הנאה אלא מניעת נזק.","ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור שכל הדברים הללו אינם נחשבים אלא מניעת נזק? \u0003אמר רב הושעיא: זו\u0004"],["\u0003דברי חנן היא\u0004 במחלוקת המבוארת להלן, שהפורע חוב עבור אדם אחר, אין לו זכות תביעה עליו שישיב לו את כספו ואינו אלא כמסיר ממנו נזק.","\u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהלכה זו של מודר הנאה היא כ\u0003דברי הכל\u0004 באותה מחלוקת, אולם נאמר הדבר \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003מודר הנאה דיהיב\u0004 \u0005[שנתן]\u0006 לו המלווה למודר את הכסף \u0003על מנת שלא לפרוע.\u0004 כלומר, התנה עימו שלא יוכל לכוף את פריעת החוב, אלא אם ירצה הלווה — ישלם לו. ובמקרה כזה לא סילק ממנו המדיר התחייבות ממונית ממש.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 היא אותה דעה של \u0003חנן\u0004 שהזכרנו? ומשיבים: \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שהלך למדינת הים\u0004 (חוץ לארץ) \u0003ועמד\u0004 אדם \u0003אחד\u0004 מרצונו \u0003ופירנס את אשתו,\u0004 ולאחר שחזר הבעל תובע ממנו המפרנס את הכסף שנתן לאשתו. \u0003חנן אמר: איבד\u0004 הנותן \u0003את מעותיו,\u0004 ואין כאן מקום לתביעה, כיון שהבעל לא התחייב לתת לו דבר, והנותן עשה זאת מרצונו.","\u0003נחלקו עליו בני כהנים גדולים, ואמרו: ישבע\u0004 הנותן \u0003כמה הוציא, ויטול. אמר ר' דוסא בן הרכינס כדבריהם\u0004 של בני כהנים גדולים. \u0003אמר ר' יוחנן בן זכאי: יפה אמר חנן,\u0004 שבכל מקרה כזה \u0003הניח מעותיו על קרן הצבי.\u0004 כלומר, סיכן את כספו בדבר שאין בו שום בטחון.","ומסבירים את טעם המחלוקת בין רבא ורב הושעיא בפירוש המשנה: \u0003רבא לא אמר כרב הושעיא\u0004 וסבר שפירושו עדיף משום \u0003דקא מוקים לה למתניתין\u0004 \u0005[שמעמיד אותה,\u0006 מסביר \u0005את משנתנו]\u0006 \u0003כדברי הכל,\u0004 ועדיף להסבירה כך מאשר להסבירה כדעת חכם אחד. ומצד שני \u0003רב הושעיא לא אמר כרבא\u0004 משום שיש מקום לגזור \u0003גזירה\u0004 ולאסור לפרוע עבור המודר מלוה שניתן על מנת \u0003שלא ליפרע משום\u0004 מלוה שניתן על מנת שיוכל לכפותו \u0003ליפרע.\u0004 ולכן הוא מסביר את המשנה דווקא כשיטת חנן שפריעת חוב של אחר אינה אלא מניעת נזק לו.","שנינו במשנה: \u0003מחזיר לו את אבידתו. פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003ר' אמי ור' אסי, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: לא שנו אלא בשנכסי\u0004 ה\u0003מחזיר אסורין על בעל\u0004 ה\u0003אבידה, דכי מהדר ליה\u0004 \u0005[שכאשר\u0006 הוא \u0005מחזיר לו] —\u0006 \u0003מידעם דנפשיה קא מהדר ליה\u0004 \u0005[דבר משל עצמו\u0006 הוא \u0005מחזיר לו].\u0006 שהרי אין האיש שנאסר בנדר נהנה כלל מחבירו, ורק את רכושו שלו הוא מקבל בחזרה. \u0003אבל\u0004 אם היה להיפך ש\u0003נכסי בעל\u0004 ה\u0003אבידה אסורין על\u0004 ה\u0003מחזיר — לא קא מהדר ליה\u0004 \u0005[אינו מחזיר לו]\u0006 מפני שאז מתברר \u0003דקא מהני ליה\u0004 \u0005[שמהנה אותו]\u0006 בעל האבידה את המחזיר בעקיפין, שהוא מרוויח על ידי כך \u0003פרוטה\u0004 של \u0003רב יוסף.\u0004 שאמר רב יוסף ששומר אבידה נחשב כשומר שכר כי העוסק במצוה אחת פטור ממצוה אחרת באותה שעה, ונמצא פטור מלתת פרוטה של צדקה לעני. ומכאן שלמשיב האבידה יש רווח מסויים מן האבידה, ואסור לו הדבר משום שהוא מודר הנאה מבעל האבידה.","\u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: אפילו\u0004 כשהיו \u0003נכסי בעל\u0004 ה\u0003אבידה אסורין על\u0004 ה\u0003מחזיר — מהדר ליה\u0004 \u0005[מחזיר לו],\u0006 \u0003ו\u0004מה שאמרת שיש בכך הנאה למחזיר \u0003משום פרוטה\u0004 של \u0003רב יוסף —\u0004 הרי דבר זה \u0003לא שכיח\u0004 \u0005[מצוי]\u0006 שיזדמן לו עני בדיוק בשעה שדואג לאבידה, ולכן אין לומר שהשבת אבידה יש בה רווח כלשהו."],["\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מקום שנוטלין עליה\u0004 על השבת אבידה \u0003שכר — תפול הנאה\u0004 זו \u0003להקדש.\u0004 ונברר: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003אפילו בשנכסי בעל\u0004 ה\u0003אבידה אסורים על\u0004 ה\u0003מחזיר נמי מהדר\u0004 \u0005[גם כן מחזיר]\u0006 \u0003היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003מקום שנוטלין עליה שכר,\u0004 שכיון שלמחזיר אסור ליהנות מבעל האבידה \u0003תפול הנאה\u0004 זו של השכר \u0003להקדש.\u0004","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003כשנכסי בעל אבידה אסורים על מחזיר לא מהדר\u0004 \u0005[מחזיר],\u0006 ואם כן, מדובר במשנתנו רק במקרה בו נכסי המחזיר אסורים על בעל האבידה, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003תפול הנאה להקדש?\u0004 הרי אין איסור למחזיר להנות מבעל האבידה!","ומשיבים: \u0003אחדא קתני\u0004 \u0005[על אחת\u0006 מהן \u0005שנה],\u0006 כלומר, באופן אחד נשנתה המשנה, במקרה בו מסרב המחזיר לקבל את שכרו, ונמצא בעל האבידה נהנה מן המחזיר במה שמשאיר את שכרו בידו, ומשום כך תיפול הנאה זו להקדש.","כל השמועה הזו כולה \u0003איכא דמתני לה בהאי לישנא\u0004 \u0005[יש ששונים אותה בלשון זו],\u0006 כדלקמן: \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה,\u0004 בכך, \u0003ר' אמי ור' אסי; חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: לא שנו\u0004 שמחזיר לו אבידתו \u0003אלא בשנכסי בעל\u0004 ה\u0003אבידה אסורין על\u0004 ה\u0003מחזיר, ומשום פרוטה\u0004 של \u0003רב יוסף\u0004 שנהנה המחזיר במה שלא חייב לתת לעני צדקה באותה שעה — \u0003לא שכיח\u0004 \u0005[מצוי].\u0006 \u0003אבל\u0004 אם היו \u0003נכסי\u0004 ה\u0003מחזיר אסורים על בעל\u0004 ה\u0003אבדה — לא מהדר ליה\u0004 \u0005[מחזיר לו]\u0006 \u0003משום דקא מהני ליה\u0004 \u0005[שמהנה אותו]\u0006 בעצם השבת האבידה.","\u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: אפילו\u0004 כש\u0003נכסי\u0004 ה\u0003מחזיר אסורים על בעל\u0004 ה\u0003אבידה — מותר.\u0004 ומדוע? \u0003דכי מהדר ליה\u0004 \u0005[שכאשר\u0006 הוא \u0005מחזיר לו] —\u0006 \u0003מידי דנפשיה קמהדר ליה\u0004 \u0005[דבר משל עצמו\u0006 הוא \u0005מחזיר לו]\u0006 ואינו נותן לו דבר חדש.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מקום שנוטלין עליה שכר — תפול הנאה להקדש. בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003אפילו בשנכסי\u0004 ה\u0003מחזיר אסורים על בעל\u0004 ה\u0003אבידה מהדר\u0004 \u0005[מחזיר]\u0006 — \u0003היינו דמתרץ\u0004 \u0005[זהו ש\u0006צריך \u0005ליישב\u0006 ולהסביר\u0005]\u0006 מה עושים ב\u0003מקום\u0004 שנוטלים שכר.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003בשנכסי מחזיר אסורין\u0004 על בעל האבידה, \u0003ולא מהדר\u0004 \u0005[ואינו מחזיר]\u0006 כלל, ומשנתנו עוסקת רק במקרה בו נכסי בעל האבידה אסורים על המחזיר, אם כן \u0003היכי מתרץ\u0004 \u0005[איך\u0006 הוא \u0005מסביר]\u0006 את ההלכה הזו של \u0003מקום\u0004 שנוטלים שכר? והרי אין בעל האבידה אסור בהנאתו של המחזיר, ומדוע לא יעכב שכרו של הלה בידו? ואומרים על כך: אכן, \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006"],["\u0003אמר רבא:\u0004 אדם ש\u0003היתה לפניו ככר\u0004 לחם \u0003של הפקר, ואמר: \"ככר זו הקדש\",\u0004 אם \u0003נטלה\u0004 אחר כך \u0003לאוכלה — מעל לפי כולה\u0004 לפי כל הערך שלה, שכיון שהתחיל לאכול ממנה נמצא שלוקח את כל הככר הזו לעצמו, ומעל בכל הככר, וחייב לשלם דמי כל הככר להקדש. אבל אם נטלה לא על מנת להשתמש בה אלא כדי \u0003להורישה לבניו — מעל\u0004 רק \u0003לפי טובת הנאה שבה,\u0004 לפי מה שנהנה מזה שהבנים מחזיקים לו טובה על שהוא מוריש להם דבר, שהרי הוא עצמו לא נהנה מן הככר עצמה כלל.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב חייא בר אבין מרבא:\u0004 אמר לחבירו \u0003\"ככרי עליך\u0004 באיסור קונם \u0003\"\u0004\u0003ונתנה לו במתנה, מהו\u0004 הדין? וצדדי השאלה: האם נדייק כי \u0003\"ככרי\" אמר לו\u0004 בנדרו, וכוונתו \u0003כי איתיה ברשותיה\u0004 \u0005[כאשר\u0006 היא \u0005ישנה ברשותו]\u0006 \u0003הוא\u0004 ש\u0003אסור,\u0004 ומשום כך כאשר נתן לו אותה במתנה ואינה עוד שלו — בטל ממנה האיסור. \u0003או דלמא\u0004 \u0005[שמא]\u0006 עיקר ההדגשה הוא במלה \u0003\"עליך\"\u0004 ש\u0003אמר ליה\u0004 \u0005[לו],\u0006 וכוונתו \u0003עילויה שויתיה\u0004 \u0005[עליך עשיתי אותה]\u0006 \u0003הקדש\u0004 גם כשתצא הככר מרשותי?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003פשיטא דאף על גב דיהבה ליה\u0004 \u0005[פשוט\u0006 הדבר \u0005שאף על פי שנתן אותה לו]\u0006 \u0003במתנה — אסור.\u0004 הקשה עליו רב חייא בר אבין: \u0003אלא\u0004 לפי זה מה שהוא אומר \u0003\"ככרי עליך\"\u0004 שהדגיש \"ככרי\" \u0003לאפוקי מאי\u0004 \u0005[להוציא,\u0006 למעט את \u0005מה]\u0006 האם אין הכוונה שאסורה הפת רק כשהיא ברשותו? \u0003לאו לאפוקי דאי גנבה מיניה מיגנב\u0004 \u0005[האם לא להוציא שאם נגנבה ממנו]\u0006 שהיא מותרת לו? ואם כן הוא הדין אם נתנה לו במתנה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003לא, לאפוקי דאי אזמניה עלה\u0004 \u0005[להוציא שאם הזמין אותו עליה],\u0006 שהזמינו קודם לאכול מאותה ככר, הרי אותו חלק של הככר שיכול המוזמן לאכול קנוי לו, ואינו יכול לאוסרו, אבל נאסר בחלק האחר שנשאר עדיין ברשות הבעלים."],["\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 לרבא ממה ששנינו, \u0003אמר לו\u0004 חבירו: \u0003\"השאילני פרתך\", אמר לו\u0004 ההוא: \u0003\"קונם\u0004 כל \u0003פרה\u0004 שיש לי \u0003שאני קנוי לך\",\u0004 כלומר, אם קניתי עוד פרה חוץ מזו שאני צריך אותה, תהיה קונם עליך, או \u0003\"נכסי\u0004 אסורים \u0003עליך\u0004 בקונם \u0003אם יש לי פרה אלא זו\"\u0004 ונתברר שיש לו פרות אחרות, או אם אמר לו \u0003\"השאילני קרדומך\",\u0004 ו\u0003אמר לו\u0004 בעל הקרדום: \u0003\"קונם קרדום שיש לי שאני קנוי\",\u0004 או \u0003\"נכסי עלי אם יש לי קרדום אלא זה\" ונמצא שיש לו\u0004 קרדום אחר, וחל איפוא הקונם — \u0003בחייו\u0004 של המדיר \u0003אסור\u0004 המודר באלה, \u0003מת\u0004 המדיר \u0003או שנתנה לו\u0004 למודר ממנו הנאה \u0003במתנה — הרי זה מותר.\u0004 משמע שכאשר נותן במתנה בטל האיסור, שלא חל הקונם אלא כל זמן שהיה הרכוש ברשותו!","\u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא:\u0004 כאן מדובר \u0003שניתנה לו על ידי אחר.\u0004 לא שנתן לו המדיר במתנה במישרין, אלא שהמדיר מכר או העביר את החפץ בדרך אחרת לאדם אחר, ואותו אדם נתן למודר במתנה. שכיון שיצא הרכוש מרשות בעליו תחילה — שוב אין עליו איסור.","ומעירים, \u0003אמר רב אשי: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 \u0003\"שניתנה לו\", ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"שנתנה לו\",\u0004 משמע שמדובר דווקא במתנה שניתנה על ידי אחר, ולא על ידי המדיר.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן:\u0004 האם \u0003יש מעילה בקונמות, או לא?\u0004 כיון שהקונם הוא כמו הקדש לגבי מי שאסור עליו, האם יש בו דין הקדש לכל דבר עד כדי כך שיהיה בו איסור מעילה וכל דיני מעילה, או לא?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[שניתם אותה]\u0006 כבר, כלומר, אפשר ללמוד דבר זה ממשנה מפורשת: \u0003מקום שנוטלין עליה שכר — תיפול הנאה להקדש. למימרא\u0004 \u0005[לומר]\u0006 וללמוד מלשון זו \u0003כי\u0004 קונם הריהו כמו \u0003הקדש, מה הקדש יש בו מעילה — אף קונמות יש בהן מעילה.\u0004","ומעירים: ובעיה זו, היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו בה. ששנינו: אמר \u0003\"קונם ככר זו הקדש\"\u0004 שאסרה בקונם לכל אדם כהקדש, \u0003ואכלה, בין הוא ובין חבירו — מעל, לפיכך יש לה פדיון\u0004 כיון שמעל בה כהקדש, הרי כמו כל הקדש שאפשר לפדות אותו. אם אמר \u0003\"ככר זו עלי להקדש\" ואכלה — הוא מעל, חבירו\u0004 שאכלה — \u0003לא מעל,\u0004 שהרי אמר \"עלי\". \u0003לפיכך אין לה פדיון\u0004 שאין זה כהקדש גמור האסור לכל. אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: בין כך ובין כך לא מעל, לפי שאין מעילה בקונמות.\u0004 הרי שיש מחלוקת אם קונם יש בו דין הקדש עד כדי מעילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי:\u0004 אמר לחבירו \u0003\"ככרי\u0004 קונם \u0003עליך\" ו\u0004אחר כך \u0003נתנה לו במתנה, מי\u0004 מהם \u0003מעל?\u0004 אם תאמר \u0003למעול\u0004 \u0005[שימעל]\u0006 ה\u0003נותן — הא לא אסירא עליה\u0004 \u0005[הרי אינה אסורה עליו]\u0006 ומדוע ייחשב כמועל? אם תאמר \u0003למעול\u0004 \u0005[שימעל]\u0006 ה\u0003מקבל — יכול דאמר\u0004 \u0005[שיאמר]:\u0006 \u0003היתירא בעיתי\u0004 \u0005[היתר רציתי]\u0006 לקבל, \u0003איסורא\u0004 \u0005[איסור]\u0006 \u0003לא בעיתי\u0004 \u0005[רציתי]\u0006 לקבל, וכיון שזה איסור אינני רוצה לקבל אותו, שאם קיבלתי ככר זו ממך — היה זה בטעות. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 ה\u0003מקבל מעל לכשיוציא,\u0004 כאשר ישתמש בככר הזו, אז יחול על כך דין מעילה, למרות שהיתה כאן קבלה בטעות. וטעמו של דבר: \u0003שכל המוציא מעות הקדש לחולין,\u0004 אפילו \u0003כסבור של חולין הוא\u0004 — הרי זה \u0003מועל.\u0004 ו\u0003אף זה,\u0004 למרות שחשב שמה שקיבל היה היתר, אם השתמש בכך — הרי זה \u0003מועל.\u0004"],["\u0003ו\u0004עוד דברים שרשאי אדם לעשות עבור המודר ממנו הנאה: \u0003תורם את תרומתו ומעשרותיו\u0004 של החבר, ובלבד שיהא זה \u0003לדעתו\u0004 (בהסכמתו) של חבירו, כי שלא מדעתו לא חלה התרומה, \u0003ומקריב עליו\u0004 (בשבילו) \u0003קיני זבין,\u0004 זוג תורים או בני יונה שמביאים לטהרת הזב, או \u0003קיני זבות,\u0004 או \u0003קיני יולדות\u0004 שמביאות לטהרתן, וכן מקריב עבורו \u0003חטאות ואשמות. ו\u0004למרות שאסור לו להנות אותו, הריהו \u0003מלמדו מדרש הלכות ואגדות, אבל לא ילמדנו מקרא. אבל מלמד הוא את בניו ואת בנותיו מקרא.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003הני כהני\u0004 \u0005[הכהנים האלו]\u0006 שמקריבים את הקרבנות, האם \u0003שלוחי דידן הוו\u0004 \u0005[שלוחים שלנו הם\u0006 נחשבים\u0005]\u0006 \u0003או שלוחי דשמיא\u0004 \u0005[שמים]\u0006 הם? ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה,\u0006 מה ההבדל למעשה\u0005]\u0006 — \u0003ל\u0004ענין \u0003מודר הנאה. אי אמרת דשלוחי דידן הוו\u0004 \u0005[אם אתה אומר ש\u0006הכהנים \u0005שלוחים שלנו הם],\u0006 הרי כהן אסור להקריב בשביל מי שהוא מודר ממנו הנאה, שבכך \u0003הא מהני ליה\u0004 \u0005[הרי\u0006 הוא \u0005מהנה אותו]\u0006 \u0003ואסור. ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 שהם \u0003שלוחי דשמיא\u0004 \u0005[שמים] —\u0006 \u0003שרי\u0004 \u0005[מותר].\u0006 אם כן \u0003מאי\u0004 \u0005[מה]\u0006 המסקנה בשאלה זו?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003מקריב עליו קיני זבין כו'.\u0004 ונדייק מכאן: \u0003אי אמרת שלוחי דידן\u0004 \u0005[אם אתה אומר\u0006 שהם \u0005שלוחים שלנו]\u0006 נמצא ש\u0003קא מהני ליה\u0004 \u0005[\u0006ש\u0005הוא מהנה אותו]\u0006 ואיך מותר הדבר? ומכאן ששלוחי שמים הם.","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה סבור שלדעת המשנה כהנים הם שלוחי שמים, \u0003ליתני\u0004 \u0005[שישנה]\u0006 באופן כללי: \u0003מקריב עליו קרבנות!\u0004 ומדוע פרט דווקא קרבנות אלה? \u0003אלא,\u0004 על כרחך צריך אתה לומר כי קרבנותיהם של \u0003מחוסרי כפרה שאני\u0004 \u0005[שונים]\u0006 ואינם דומים לקרבנות אחרים. ש\u0003אמר ר' יוחנן: הכל צריכין דעת,\u0004 שכל קרבן צריך שיביא אותו המקריב מדעתו ומרצונו, \u0003חוץ ממחוסרי כפרה,\u0004 שמביאים קרבנות כדי לגמור את טהרתם. והוכחה לדבר, \u0003שהרי אדם מביא קרבן\u0004 זה \u0003על\u0004 (עבור) \u0003בניו ועל בנותיו הקטנים\u0004 כשהם מחוסרי כפרה, למרות שאין בהם דעת, \u0003שנאמר: \"זאת תורת הזב\"\u0004 (ויקרא טו, לב), ודרשו: \u0003בין גדול בין קטן.\u0004","ושואלים: \u0003אלא מעתה ל\u0004דעת \u0003ר' יוחנן\u0004 מה שנאמר \u0003\"זאת תורת הילדת\" וגו'\u0004 (ויקרא יב, ז) גם כן יפרש \u0003בין\u0004 יולדת \u0003קטנה ובין גדולה?\u0004 וכי \u0003קטנה בת לידה היא?! והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003רב ביבי קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן\u0004 ברייתא זו: \u0003שלש נשים משמשות\u0004 עם בעליהן \u0003במוך,\u0004 שמכניסות בבית הרחם כדי שלא תכנסנה להריון, והן: \u0003קטנה ומעוברת ומניקה.\u0004 והטעם שהתירו ל\u0003קטנה\u0004 לנקוט באמצעי מניעה מהריון — \u0003שמא תתעבר ותמות.\u0004 ומכאן נלמד שקטנה אינה מסוגלת ללדת, שהרי היא מתה עוד קודם לכן!","ומסבירים: \u0003ההיא\u0004 \u0005[אותו]\u0006 ריבוי של \u0003\"זאת תורת היולדת\"\u0004 לא בא לרבות קטנה, אלא לרבות ענין אחר: \u0003בין\u0004 שהיא \u0003פקחת בין שוטה, שכן אדם מביא קרבן על אשתו\u0004 כשהיא \u0003שוטה,\u0004","\u0003כדברי ר' יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: אדם מביא קרבן עשיר על אשתו.\u0004 שיש הבדל בקרבנות היולדת בין עניה ועשירה, וגם אם היולדת עצמה אין לה נכסים, ולפי רכושה היתה צריכה להביא רק קרבן עני, כיון שהיא נשואה לעשיר — חייב להביא עבורה קרבן עשיר, \u0003ו\u0004כן מביא עבורה \u0003כל קרבנות שחייבת,\u0004","\u0003שכך כותב לה\u0004 בכתובה: \u0003ו\u0004כל \u0003אחריות,\u0004 כל התחייבויות \u0003דאית ליך\u0004 \u0005[שיש לך]\u0006 \u0003עלי מן קדמת דנא\u0004 \u0005[מקודם לכן],\u0006 שהבעל חייב לספק לאשתו גם קרבנות למלא את כל התחייבויותיה, ואין הבדל בין זו שיש בה דעת ובין זו שאין בה דעת. ואם כן אין להוכיח ממשנתנו שהכהנים שלוחי שמים הם, שהרי בקרבנות אלו אין צריכים דעתו של מי שמקריבים עבורו."],["\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב שימי בר אבא\u0004 ממה ששנינו: \u0003אם היה כהן\u0004 מדיר הנאה את חבירו, מכל מקום \u0003יזרוק עליו\u0004 את \u0003דם חטאתו ודם אשמו.\u0004 הרי שיכול לעשות את עבודת כל הקרבנות עבורו, ואף אלו שצריכים דעת המתכפר!","ודוחים: כאן מדובר רק ב\u0003דם חטאתו של מצורע ודם אשמו של מצורע\u0004 וקרבנות אלה הם של מחוסר כפרה, שמביאם המצורע לגמור טהרתו. \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"זאת תהיה תורת המצרע\"\u0004 (ויקרא יד, ב) ודרשו: \u0003בין גדול ובין קטן,\u0004 משמע שאף עבור הקטן (שאין בו דעת) מביאים קרבן זה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכהנים שפיגלו במקדש,\u0004 שבזמן אחת מעבודות הקרבן חשב הכהן לאכול ממנו או להקטירו חוץ לזמנו הראוי ובמקרה זה נפסל הקרבן בכך, אם היו \u0003מזידין — חייבין\u0004 לשלם. ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם היו \u0003שוגגין — פטורין, אלא שפיגולן\u0004 מכל מקום \u0003פיגול\u0004 והקרבן נפסל.","ולענייננו, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שהכהנים \u0003שלוחי דשמיא הוו\u0004 \u0005[שמים הם]\u0006 \u0003היינו\u0004 \u0005[זוהי]\u0006 הסיבה \u0003שפיגולן פיגול,\u0004 שכן מה שהם עושים אינו מכוח בעל הקרבן אלא מכוח עצמם כשלוחי שמים. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 כי \u0003שלוחי דידן הוו\u0004 \u0005[שלוחים שלנו הם],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003פיגולן פיגול? לימא ליה\u0004 \u0005[שיאמר לו]\u0006 בעל הקרבן לכהן: \u0003שליחא שויתיך לתקוני\u0004 \u0005[שליח עשיתי אותך לתקן]\u0006 \u0003ולא לעוותי\u0004 \u0005[לקלקל]!\u0006","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 הדבר \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003פיגול,\u0004 כיון ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 וחזר והדגיש \u0003\"לא יחשב לו\"\u0004 (ויקרא ז, יח) לרבות פיגול \u0003מכל מקום,\u0004 אף שמפגל שלא ברשות הבעלים, מכל מקום הקרבן נפסל. ואין מכאן איפוא ראיה לשאלת שליחותם של הכהנים.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של הלכה זו שהזכרנו בדיון הקודם \u0003אמר ר' יוחנן: הכל צריכין דעת חוץ ממחוסר כפרה\u0004 שאפשר להביא קרבן כפרה לטהרו אפילו שלא בידיעתו, וראיה לדבר — \u0003שהרי אדם מביא קרבן\u0004 של מחוסר כיפורים לגמר טהרה \u0003על\u0004 (עבור) \u0003בניו ועל בנותיו הקטנים.\u0004 ושואלים: \u0003אלא מעתה יביא אדם\u0004 גם \u0003חטאת חלב\u0004 (כלומר, חטאת הבאה לכפרת עבירה שיש בה חיוב כרת, כגון אכילת חלב) \u0003על חבירו\u0004 שלא מדעתו על סמך אותו שיקול, \u0003שכן אדם מביא\u0004 קרבן \u0003על אשתו שוטה כ\u0004דברי \u0003ר' יהודה. אלמה\u0004 \u0005[מדוע]\u0006 \u0003אמר ר' אלעזר: הפריש חטאת חלב על חבירו — לא עשה כלום!\u0004","את הקושיה הזו דוחים על ידי בירור הדברים: \u0003אשתו שוטה היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003אכלה\u0004 את החלב \u0003כשהיא שוטה — הלא לאו\u0004 \u0005[לא]\u0006 \u0003בת קרבן היא,\u0004 שאין עליה חיוב קרבן כלל, לפי שמי שאין בו דעת אינו חייב בעונשים ובכפרה.","\u0003ואי\u0004 \u0005[ואם]\u0006 מדובר באופן ש\u0003אכלה כשהיא פקחת, ונשתטית\u0004 לאחר מכן — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר ר' ירמיה אמר ר' אבהו אמר ר' יוחנן: אכל חלב והפריש קרבן, ונשתטה,\u0004 גם כאשר \u0003חזר ונשתפה — פסול\u0004 הקרבן, \u0003הואיל ונדחה\u0004 בשעה שהיה שוטה — \u0003ידחה\u0004 לעולם. מכאן שחטאת זו שמביא אדם על אשתו שוטה אינה חטאת חלב לכפרת עוונות, אלא רק של גמר טהרה, כגון של יולדת, שבה אין צריך דעת. ואם כן עולה כי השאלה לגבי הקרבת חטאת חלב עבור חבירו לא היתה מבוססת מעיקרה.","ושואלים עוד: \u0003אלא מעתה\u0004 לפי אותה דרך הוכחה \u0003יביא אדם\u0004 קרבן \u0003פסח על\u0004 (עבור) \u0003חבירו\u0004 שלא מדעתו \u0003שכן אדם מביא\u0004 קרבן פסח \u0003על בניו ועל בנותיו הקטנים\u0004 שאין בהם דעת. \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003אמר ר' אלעזר\u0004 שאם \u0003הפריש פסח על חבירו לא עשה כלום!\u0004","\u0003אמר ר' זירא: \"שה לבית אבת\u0004 שה לבית\u0003\"\u0004 (שמות יב, ג), כלומר, הנוהג שכל אנשי ביתו של אדם ואף בניו ובנותיו הקטנים נמנים מראש על קרבן הפסח \u0003לאו דאורייתא\u0004 \u0005[אינו\u0006 \u0005מן התורה].\u0006","\u0003וממאי\u0004 \u0005[וממה],\u0006 מהיכן אנחנו למדים דבר זה — \u0003מדתנן\u0004 \u0005[ממה ששנינו\u0006 במשנה\u0005]:\u0006 \u0003האומר לבניו\u0004 הקטנים: \u0003\"הריני שוחט את הפסח על מי שיעלה מכם ראשון לירושלים\",\u0004 שהוא זה שיזכה לאכול מן הקרבן שאני שוחט, \u0003כיון שהכניס ראשון ראשו ורובו\u0004 לירושלים — \u0003זכה בחלקו, ומזכה את אחיו עמו. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי חובת \u0003\"שה לבית\"\u0004 הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 שחובה היא על הקטנים להשתתף בו, \u0003על בישרא קאי ומזכי להו\u0004 \u0005[על הבשר\u0006 הוא \u0005עומד ומזכה להם]?!\u0006 שאמנם הבן שמגיע ראשון — זכה בחלקו לפי התנאי, אבל לאחר שהקרבן כבר נשחט — כיצד יכול הוא לאחר מכן לזכות גם לאחרים? אלא ודאי אין הקטנים צריכים להימנות מראש על הפסח מן התורה כלל.","ומעירים: \u0003אלא\u0004 אם כך הוא \u0003למה להו\u0004 \u0005[להם]\u0006 ש\u0003אמר להון אבוהון\u0004 \u0005[להם אביהם]\u0006 שהראשון יזכה בפסח, כאשר לאמיתו של דבר אין זו זכיה אמיתית בקרבן? יש להסביר שאמר זאת \u0003כדי לזרזן במצות. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מעשה היה\u0004 שאמר האב לבניו ולבנותיו שיתחרו ביניהם מי מהם יגיע ראשון להקרבת הפסח \u0003וקדמו בנות לבנים, ונמצאו בנות זריזות ובנים שפלים\u0004 (עצלים). וכיון שלא אמר \"בנות זכו\" משמע שהיה זה ענין של זירוז, אבל לא דין של זכיה בקרבן.","שנינו במשנה כי המדיר את חבירו \u0003תורם את תרומותיו כו'.\u0004"],["\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003התורם מ\u0004התבואה \u0003שלו על\u0004 התבואה \u0003של חבירו,\u0004 האם על מנת שתחול התרומה \u0003צריך\u0004 לכך את \u0003דעתו\u0004 של בעל התבואה, \u0003או לא?\u0004 וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון\u0004 ש\u0003זכות הוא לו\u0004 שתהא תבואתו מתוקנת והרי הוא מזכה אותו בכך שתורם לו משלו ונותן לו דבר במתנה, לכן \u0003לא צריך דעת,\u0004 שיכול אדם לזכות לחבירו שלא מדעתו. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מצוה דיליה\u0004 \u0005[שלו]\u0006 של בעל התבואה \u0003היא\u0004 לתרום תרומה, \u0003וניחא ליה למיעבדיה\u0004 \u0005[ונוח לו לעשות אותה]\u0006 בעצמו, ואם כן כשעושה זאת אדם אחר, אין זו זכות עבורו.","ומביאים ראיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003תורם\u0004 המדיר \u0003את תרומותיו ואת מעשרותיו\u0004 של המודר \u0003לדעתו.\u0004 ונברר: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהוא תורם \u0003מן\u0004 הרכוש של \u0003בעל הכרי על\u0004 הרכוש \u0003של בעל הכרי,\u0004 יש לברר: \u0003ולדעתו דמאן\u0004 \u0005[של מי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לדעתו דיליה\u0004 \u0005[שלו,\u0006 של התורם\u0005]\u0006 — \u0003מאן שוויה\u0004 \u0005[מי מינהו]\u0006 \u0003שליח\u0004 לתרום? הלא בודאי אינו יכול לתרום משל חבירו.","\u0003אלא\u0004 צריכים לומר כי תורם הוא \u0003לדעתו\u0004 של \u0003בעל הכרי,\u0004 אולם במקרה כזה \u0003הא קמהני ליה דקעביד שליחותיה\u0004 \u0005[הרי\u0006 הוא \u0005מהנה אותו\u0006 בכך \u0005שעושה שליחותו]!\u0006 \u0003אלא\u0004 חייבים אנחנו לומר שמדובר שהוא תורם \u0003משלו על של\u0004 בעל \u0003הכרי.\u0004 ונברר: \u0003ולדעתו דמאן\u0004 \u0005[של מי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003לדעתו\u0004 של \u0003בעל הכרי\u0004 הוא תורם — \u0003הא קמהני ליה\u0004 \u0005[הרי\u0006 הוא \u0005מהנה אותו]\u0006 בכך שעושה את שליחותו! \u0003אלא לאו לדעתיה דנפשיה\u0004 \u0005[האם לא לדעת עצמו,\u0006 של התורם\u0005]\u0006 \u0003ומשלו תורם על של חבירו. ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 כי \u0003צריך דעת — הא קמהני ליה\u0004 \u0005[הרי\u0006 הוא \u0005מהנה אותו]!\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נלמד מכאן שתורם משלו על של חבירו \u0003אין צריך דעת.\u0004","ודוחים: \u0003לעולם\u0004 אפשר לומר שמפריש \u0003משל בעל הכרי על בעל הכרי,\u0004 אלא שכאן אין מדובר שעשה את המודר שליח במפורש, אלא \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רבא\u0004 לענין אחר: \u0003באומר \"כל הרוצה לתרום יבא ויתרום\", הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003באומר\u0004 שכל הרוצה לתרום יתרום, ונמצא שתורם מדעתו אף שאין נעשה לו שליח.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' ירמיה מר' זירא: התורם מ\u0004פירות \u0003שלו על\u0004 פירות טבל \u0003של חבירו, טובת הנאה של מי?\u0004 כלומר, אותה הנאה שהוא יכול לקבל מפני שהוא נותן את התרומה לכהן מסויים, למי היא שייכת? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 \u0003אי לאו פירי דהאיך, מי מתקנא כריא\u0004 \u0005[אם לא\u0006 ה\u0005פירות של זה\u0006 התורם, \u0005האם היה מתוקן הכרי,\u0006 ערימת הפירות\u0005]\u0006 של \u0003ההוא,\u0004 של בעל התבואה, ואם כן, טובת הנאה של התורם היא. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אי לאו כריא\u0004 \u0005[אם לא הכרי]\u0006 של \u0003ההוא, לא הויין פירי דהדין\u0004 \u0005[היו\u0006 ה\u0005פירות של זה]\u0006 \u0003תרומה,\u0004 והדבר תלוי בבעל הכרי, וטובת ההנאה היא שלו?","\u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"עשר תעשר \u0003את כל תבואת זרעך... ונתת\u0004 ה\" (דברים יד, כב. דברים יד, כו), לומר שכל טובת ההנאה שבנתינה שייכת לבעל הכרי (\"זרעך\").","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' ירמיה לר' זירא: הרי שנינו: \u0003תורם את תרומותיו ואת מעשרותיו לדעתו. ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 כי \u0003טובת הנאה\u0004 של \u0003בעל הכרי,\u0004 אם כן \u0003הא קא מהני ליה\u0004 \u0005[הרי\u0006 התורם \u0005מהנה אותו],\u0006 שהרי בעל הכרי מקבל את טובת ההנאה באותה נתינה! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003טובת הנאה דיליה\u0004 \u0005[שלו\u0006 היא\u0005]\u0006 של התורם. \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא,\u0004 אפשר לומר שהוא תורם \u0003משל בעל הכרי על של בעל הכרי, ולדעתו\u0004 של \u0003בעל הכרי,\u0004 ומדובר \u0003באומר \"כל הרוצה לתרום יבא ויתרום\"\u0004 ואינו שליחו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלתו של ר' ירמיה ממה ש\u0003אמר ר' אבהו אמר ר' יוחנן:\u0004 המקדיש קרבן עבור חבירו, ונעשה בעל מום — רק \u0003המקדיש מוסיף חומש\u0004 אם רוצה לפדות אותו, ולא המתכפר, \u0003ומתכפר,\u0004 זה שלמענו הופרש הקרבן — דווקא הוא \u0003עושה תמורה,\u0004 שגוף הקרבן נחשב כשלו, ורק הוא יכול להמיר אותו באחר. \u0003והתורם משלו על שאינו שלו — טובת הנאה שלו,\u0004 של התורם.","שנינו במשנה כי אף על פי שאדם מודר הנאה מחבירו, מכל מקום הריהו \u0003מלמדו מדרש הלכות ואגדות אבל לא ילמדנו מקרא.\u0004 שואלים: \u0003מקרא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא ילמדנו — משום דקמהני ליה\u0004 \u0005[שהוא מהנה אותו]\u0006 בלימודו, \u0003מדרש נמי\u0004 \u0005[גם כן]\u0006 הלא \u0003קמהני ליה\u0004 \u0005[הוא מהנה אותו]!\u0006 \u0003אמר שמואל:\u0004 כאן מדובר \u0003במקום שנוטלין שכר על\u0004 הוראת \u0003המקרא\u0004 ונמצא המודר מרוויח בכך שאינו משלם לו שכרו — \u0003ואין נוטלין שכר על\u0004 הוראת \u0003המדרש.\u0004 ושואלים: \u0003מאי פסקא\u0004 \u0005[מה החיתוך],\u0006 מדוע אתה מפרש שנוטלים שכר על מקרא דווקא ולא על דבר אחר?"],["\u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003אפילו במקום שנוטלין שכר, על\u0004 לימוד \u0003המקרא שרי למשקל\u0004 \u0005[מותר לקחת],\u0006 אבל \u0003על\u0004 לימוד \u0003המדרש לא שרי למשקל\u0004 \u0005[אינו מותר לקחת]\u0006 שכר.","ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003מדרש\u0004 ש\u0003לא\u0004 יטול שכר עבורו — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדברי משה אל העם: \u0003\"ואתי צוה ה' בעת ההיא ללמד אתכם\u0004 חוקים ומשפטים\u0003\"\u0004 (דברים ד, יד), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ראה למדתי אתכם חקים ומשפטים כאשר צוני ה'\u0004 אלהי לעשות כן בקרב הארץ אשר אתם באים שמה לרשתה\u0003\"\u0004 (דברים ד, ה), ונלמד מכאן: \u0003מה אני\u0004 מלמד אתכם \u0003בחנם — אף אתם\u0004 תלמדו אחרים \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003בחנם.\u0004 ואם כן \u0003מקרא נמי\u0004 \u0005[גם כן]\u0006 נלמד מאותו פסוק שילמד \u0003בחנם!\u0004","\u0003רב אמר:\u0004 מה שמקבל שכר על המקרא אינו על גוף התורה שהוא מלמד, אלא \u0003שכר שימור,\u0004 שכיון שמקרא מלמדים ילדים קטנים, הרי המלמד מקבל שכר על מה שהוא שומר אותם וזה הותר לו, מה שאין כן לימוד מדרש הוא לגדולים שאינם צריכים שימור ולכך השכר הוא על עצם הלימוד והוזהרו ללמד בחינם. \u0003ור' יוחנן אמר: שכר פיסוק טעמים,\u0004 שמקבל שכר לא על גוף המקרא שמלמד, אלא על שמלמד פיסוק טעמים של המקרא, שאינו גופו של מקרא, ומותר ליטול שכר עבור זה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 שהמדיר את חבירו \u0003לא ילמדנו מקרא. בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי השכר שמקבל המלמד עבור לימוד מקרא הוא \u0003שכר פיסוק טעמים — היינו\u0004 \u0005[זהו]\u0006 הטעם ש\u0003לא ילמדנו\u0004 מקרא — שהרי צריך היה לשלם לו שכר על פיסוק הטעמים, וכיון שאינו משלם לו הריהו מהנהו בכך, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי זהו \u0003שכר שימור\u0004 — וכי \u0003גדול בר\u0004 \u0005[בן]\u0006 \u0003שימור הוא\u0004 וצריך לשלם שכר עבור זה? ואם כן אין פה הנאה ומדוע אסור בכך? ומשיבים: \u0003בקטן קתני\u0004 \u0005[שנה],\u0006 כלומר, כאן מדובר במקרה בו מודר ההנאה הוא קטן, ויש בו ענין של שימור.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בקטן,\u0004 אם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003אבל מלמד את בניו מקרא,\u0004 וכי \u0003קטן בר\u0004 \u0005[בעל]\u0006 \u0003בנים הוא?!\u0004 ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003לא ילמדנו מקרא — בקטן,\u0004 אבל \u0003אם היה גדול — מלמדו לו ולבניו מקרא,\u0004 כיון שכאמור אינו אלא שכר שימור.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: \u0003תינוקות לא קורין בתחילה,\u0004 כלומר, אין לומדים לקרוא \u0003בשבת\u0004 קטע חדש שלא למדוהו קודם, \u0003אלא שונין בראשון,\u0004 מותר להם לחזור על מה שלמדו כבר בראשונה. \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי שכר לימוד המקרא הוא \u0003שכר פיסוק טעמים — היינו\u0004 \u0005[זוהי]\u0006 הסיבה ש\u0003אין קורין בתחילה בשבת,\u0004 שהרי המלמד אותם צריך לקבל שכר על פיסוק הטעמים. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי זהו \u0003שכר שימור,\u0004 אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין קורין בתחילה בשבת ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003שונין בראשון? הא איכא\u0004 \u0005[הרי יש]\u0006 \u0003שכר שימור\u0004 של \u0003שבת,\u0004 ולענין שימור אין הבדל בין קריאה ראשונה לחזרה!","ומשיבים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 \u0003שכר פיסוק בשבת מי\u0004 \u0005[האם]\u0006 \u0003אסור?\u0004 הרי \u0003הבלעה היא,\u0004 שהרי אין המלמד מקבל שכר עבור עבודת שבת בלבד, אלא מקבל שכר עבור לימודם כל השבוע, ונמצא ששכר שבת מובלע בשכר הכללי שהוא מקבל, \u0003והבלעה\u0004 הלא \u0003מישרא שרי\u0004 \u0005[מותרת\u0006 היא\u0005]:\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003השוכר את הפועל לשמור את התינוק,\u0004 או \u0003לשמור את הפרה,\u0004 או \u0003לשמור את הזרעים — אין נותנין לו שכר שבת,\u0004 שאסור לקבל שכר עבור עבודה בשבת. \u0003לפיכך\u0004"],["\u0003אם אבדו\u0004 בשבת \u0003אינו חייב באחריותן —\u0004 שהרי אינו נחשב כשומר ביום זה. \u0003ואם היה שכיר שבת\u0004 (שבוע), או \u0003שכיר חדש,\u0004 או \u0003שכיר שנה,\u0004 או \u0003שכיר שבוע\u0004 (שבע שנים) — \u0003נותן לו שכר\u0004 מה שעושה ב\u0003שבת\u0004 בתוך שכרו, ו\u0003לפיכך אם אבדו\u0004 בשבת — \u0003חייב באחריותן.\u0004 משמע שאם מבליע את שכר השבת במשכורת כללית אין איסור בקבלת שכר על מה שהוא עושה בהיתר בשבת.","\u0003אלא\u0004 צריך לומר כך: ל\u0003גבי שבת היינו טעמא\u0004 \u0005[זה הטעם]\u0006 ש\u0003אין קוראין בתחילה — משום דיפנו אבהתהון דינוקי למצותא דשבתא\u0004 \u0005[כדי שיתפנו אבותיהם של התינוקות למצות\u0006 ועונג \u0005השבת]\u0006 ואם היה מלמד את הילדים דבר חדש יצטרכו האבות לעזור לתינוקות בלימודם וממעטים בכך במצות עונג שבת. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 טעם אחר: \u0003משום דבשבתא אכלין ושתין ויקיר עליהון עלמא\u0004 \u0005[שבשבת אוכלים\u0006 התינוקות \u0005ושותים\u0006 יותר \u0005וכבד עליהם העולם],\u0006 כלומר, ראשם כבד, ואינם מסוגלים ללמוד היטב. \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003שמואל: שינוי וסת\u0004 (הרגל) באכילה וכיוצא בו הוא \u0003תחילת חולי מעיים,\u0004 ומכיון שבשבת אוכלים מאכלים מרובים ומשובחים יותר מבשאר ימי השבוע התינוקות מרגישים חולשה מסויימת, ולכן לא ילמדם דבר חדש שמצריך ריכוז יתר.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 שהשכר שמקבל על המקרא הוא \u0003שכר פיסוק טעמים,\u0004 ומשום כך לא ילמד המדיר את בניו ובנותיו של המודר מקרא, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 שהטעם הוא משום \u0003שכר שימור?\u0004 ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003בנות\u0004 שאף הן בכלל האיסור \u0003מי קא בעיין\u0004 \u0005[האם צריכות]\u0006 \u0003שימור?\u0004 שהרי הן יושבות בביתן ואינן רגילות לצאת.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 כי זהו \u0003שכר שימור, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר שכר פיסוק טעמים?\u0004 ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 כי \u0003(שכר) פיסוק טעמים דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא.\u0004 כלומר, אין זו תוספת הוראה שאינה שייכת לתורה, אלא היא חלק מן התורה עצמה ועל כך בודאי יש איסור לקבל שכר.","ש\u0003אמר ר' איקא בר אבין אמר רב חננאל אמר רב: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ויקראו בספר בתורת האלהים מפרש ושום שכל ויבינו במקרא\"\u0004 (נחמיה ח, ח). ומסבירים: \u0003\"ויקראו בספר בתורת האלהים\" — זה מקרא\u0004 עצמו, \u0003\"מפרש\" — זה תרגום, \"ושום שכל\" — אלו הפסוקים\u0004 היכן כל אחד מהם מסתיים. \u0003\"ויבינו במקרא\" — זה פיסוק טעמים,\u0004 שעל ידם אפשר להבין כוונת הפסוקים. \u0003ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]:\u0006 \u0003אלו המסורות\u0004 (מסורת הקריאה במקרא). מכל מקום רואים שרב סבור שפיסוק טעמים הוא חלק מעיקר לימוד התורה.","ובאותו ענין \u0003אמר ר' יצחק: מקרא סופרים,\u0004 האופן שבו קוראים את המילים, \u0003ועיטור סופרים,\u0004 כאשר יבואר, \u0003ו\u0004הפסוקים שיש בהם מילים שהן \u0003קריין ולא כתיבן\u0004 \u0005[נקראות ואינן כתובות],\u0006 \u0003וכתיבן ולא קריין\u0004 \u0005[וכתובות ואינן נקראות]\u0006 — כל אלה הם \u0003הלכה למשה מסיני.\u0004","ומסבירים: \u0003מקרא סופרים\u0004 הוא כגון שבמקום שיש בו הפסק גדול אומרים: \u0003ארץ, שמים, מצרים\u0004 (בקמץ).","\u0003עיטור סופרים\u0004 הם ביטויים כגון — \u0003\"אחר תעברו\"\u0004 (בראשית יח, ה), \u0003\"אחר תלך\"\u0004 (בראשית כד, נה), \u0003\"אחר תאסף\"\u0004 (במדבר לא, ב), \u0003\"קדמו שרים אחר נגנים\"\u0004 (תהלים סח, כו), \u0003\"צדקתך כהררי אל\"\u0004 (במדבר לו, ז) — שבכל אלה יש צורך להבין את המקרא בצורה שונה קצת ממה שנשמע תחילה, והוא הקרוי עיטור סופרים.","מילים שהן \u0003קריין ולא כתיבן\u0004 \u0005[נקראות ואינן כתובות]\u0006 כגון המלה \u0003\"פרת\"\u0004 שנמצאת בפסוק \u0003\"בלכתו\u0004 להשיב ידו בנהר פרת\u0003\"\u0004 (שמואל ב ח, ג), המלה \u0003\"איש\"\u0004 בפסוק \u0003\"כאשר ישאל איש בדבר האלהים\"\u0004 (שמואל ב טז, כג), המלה \u0003\"באים\"\u0004 שבפסוק \"הנה ימים באים ו\u0003נבנתה\u0004 העיר לה'\" (ירמיה לא, לז), המלה \u0003\"לה\"\u0004 בפסוק \u0003\"\u0004אל יהי לה \u0003פליטה\"\u0004 (שמואל ב נ, כט), המלה \u0003\"את\"\u0004 של \u0003\"הגד הגד\u0004 לי את כל אשר עשית את חמותך\u0003\"\u0004 (רות ב, יא), והמלה \u0003\"אלי\"\u0004 שבפסוק \"כל אשר תאמרי אלי אעשה\" שבפסוק שאחריו נאמר \u0003\"\u0004ותרד \u0003הגרן\"\u0004 (רות ג, ו), והמלה \u0003\"אלי\"\u0004 שבפסוק \"שש \u0003השערים\u0004 האלה נתן לי כי אמר אלי אל תבואי ריקם אל חמותך\" (רות ג, יז), \u0003הלין\u0004 \u0005[אלה]\u0006 המילים שהן \u0003קריין ולא כתבן\u0004 \u0005[נקראות ואינן כתובות]\u0006 במקרא.","\u0003ו\u0004מילים שהן \u0003כתבן ולא קריין\u0004 \u0005[כתובות ואינן נקראות]\u0006 — כגון המלה \u0003\"נא\"\u0004 של \u0003\"יסלח\u0004 נא\u0003\"\u0004 (מלכים ב ה, יח)."]]};
